package com.revalclan.clanbrowser;

import com.revalclan.RevalClanPlugin;
import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;
import net.runelite.client.plugins.PluginManager;
import javax.swing.Timer;
import java.awt.Window;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.nio.file.Path;
import javax.imageio.ImageIO;

/** Starts the real local client and opens the browser directly without sending chat. */
public class BrowserClientPreview {
    public static void main(String[] args) throws Exception {
        ExternalPluginManager.loadBuiltin(RevalClanPlugin.class); RuneLite.main(args);
        String command = System.getProperty("reval.browserCommand", "leaderboard clog").replace('|', ' ');
        Timer ready = new Timer(1000, null);
        ready.addActionListener(event -> {
            if (RuneLite.getInjector() == null) return;
            PluginManager plugins = RuneLite.getInjector().getInstance(PluginManager.class);
            RevalClanPlugin reval = (RevalClanPlugin) plugins.getPlugins().stream()
                .filter(plugin -> plugin instanceof RevalClanPlugin && plugins.isPluginActive(plugin)).findFirst().orElse(null);
            if (reval == null) return;
            reval.getInjector().getInstance(ClanBrowserManager.class).open(BrowserCommand.parse(command));
            System.out.println("Opened local RuneLite clan browser: " + command); ready.stop();
            String screenshot = System.getProperty("reval.browserScreenshot");
            if (screenshot != null) captureWhenReady(screenshot);
        }); ready.start();
    }
    private static void captureWhenReady(String path) {
        Timer capture = new Timer(1000, null);
        capture.addActionListener(event -> {
            for (Window candidate : Window.getWindows()) if (candidate instanceof ClanBrowserWindow && candidate.isShowing()) {
                ClanBrowserWindow window = (ClanBrowserWindow) candidate;
                if (window.currentView() == null) return;
                try {
                    BufferedImage image = new BufferedImage(window.getContentPane().getWidth(), window.getContentPane().getHeight(), BufferedImage.TYPE_INT_ARGB);
                    Graphics2D g = image.createGraphics(); window.getContentPane().printAll(g); g.dispose();
                    ImageIO.write(image, "png", Path.of(path).toFile());
                    System.out.println("RuneLite browser render saved: " + path); capture.stop();
                } catch (Exception error) { error.printStackTrace(); capture.stop(); }
            }
        }); capture.start();
    }
}

package com.revalclan.clanbrowser;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Map;
import javax.imageio.ImageIO;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import okhttp3.OkHttpClient;

/** Desktop QA harness: production window and live read-only API, without needing a game login. */
public class BrowserDesktopPreview {
    public static void main(String[] args) throws Exception {
        com.formdev.flatlaf.FlatDarkLaf.setup();
        Gson gson = new Gson(); Map<Integer, BufferedImage> icons = new java.util.HashMap<>();
        String atlasPath = System.getProperty("reval.browserAtlas");
        if (atlasPath != null) {
            Path path = Path.of(atlasPath); BufferedImage atlas = ImageIO.read(path.resolve("items.png").toFile());
            JsonObject data = gson.fromJson(Files.readString(path.resolve("items.json")), JsonObject.class);
            data.entrySet().forEach(entry -> {
                JsonObject sprite = entry.getValue().getAsJsonObject();
                icons.put(Integer.parseInt(entry.getKey()), atlas.getSubimage(sprite.get("x").getAsInt(), sprite.get("y").getAsInt(), sprite.get("width").getAsInt(), sprite.get("height").getAsInt()));
            });
        }
        BrowserCommand command = BrowserCommand.parse(System.getProperty("reval.browserCommand", "reval clog forestry Valgusruum").replace('|', ' '));
        BrowserApi api = new BrowserApi(new OkHttpClient(), gson);
        SwingUtilities.invokeLater(() -> {
            ClanBrowserWindow window = new ClanBrowserWindow(null, api, icons::get); window.identity(0, "Valgusruum"); window.open(command);
            window.setSize(Integer.getInteger("reval.browserWidth", window.getWidth()), Integer.getInteger("reval.browserHeight", window.getHeight()));
            String screenshot = System.getProperty("reval.browserScreenshot");
            if (screenshot != null) {
                Timer timer = new Timer(350, null);
                timer.addActionListener(event -> {
                    BrowserModels.View view = window.currentView(); if (view == null) return;
                    try {
                        BufferedImage image = new BufferedImage(window.getContentPane().getWidth(), window.getContentPane().getHeight(), BufferedImage.TYPE_INT_ARGB);
                        Graphics2D g = image.createGraphics(); window.getContentPane().printAll(g); g.dispose(); ImageIO.write(image, "png", Path.of(screenshot).toFile());
                        System.out.println("Browser screenshot saved: " + screenshot); timer.stop();
                        if (Boolean.getBoolean("reval.browserExitAfterCapture")) { window.dispose(); System.exit(0); }
                    } catch (Exception error) { throw new RuntimeException(error); }
                }); timer.start();
            }
        });
    }
}

package com.revalclan;

import com.revalclan.collectionlog.CollectionLogManager;
import com.revalclan.combatachievements.CombatAchievementManager;
import com.revalclan.diaries.AchievementDiaryManager;
import com.revalclan.pbs.ClogPersonalBestCapture;
import com.revalclan.pbs.PersonalBestManager;
import com.revalclan.player.PlayerManager;
import com.revalclan.quests.QuestManager;
import com.revalclan.util.SyncStateManager;
import com.revalclan.util.Worlds;
import net.runelite.api.Client;
import net.runelite.api.gameval.VarClientID;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.HashMap;
import java.util.Map;

/**
 * Collects ALL player data by coordinating various managers
 */
@Singleton
public class PlayerDataCollector {
	@Inject
	private Client client;

	@Inject
	private PlayerManager playerManager;

	@Inject
	private QuestManager questManager;

	@Inject
	private AchievementDiaryManager achievementDiaryManager;

	@Inject
	private CombatAchievementManager combatAchievementManager;

	@Inject
	private CollectionLogManager collectionLogManager;

	@Inject
	private PersonalBestManager personalBestManager;

	@Inject
	private ClogPersonalBestCapture clogPersonalBestCapture;

	@Inject
	private SyncStateManager syncStateManager;

	/**
	 * Full payload for SYNC — the only path that carries the collection log.
	 */
	public Map<String, Object> collectSyncData() {
		Map<String, Object> data = collectFullState();
		data.put("collectionLog", collectionLogManager.sync());
		attachFingerprint(data);
		return data;
	}

	/**
	 * LOGIN/LOGOUT payload: slim (player + fingerprint) when unchanged since
	 * the last acked fingerprint, full otherwise. Never carries the collection
	 * log — no real scan exists at boundaries.
	 */
	public Map<String, Object> collectBoundaryData() {
		Map<String, Object> data = collectFullState();

		String fingerprint = attachFingerprint(data);
		if (fingerprint != null) {
			String acked = syncStateManager.getAckedFingerprint(client.getAccountHash());
			if (fingerprint.equals(acked)) {
				Map<String, Object> slim = new HashMap<>();
				slim.put("player", data.get("player"));
				slim.put("syncFingerprint", fingerprint);
				data = slim;
			}
		}

		// Jagex's own "Time played" (minutes): a server snapshot the client receives at
		// every login/hop, independent of the summary tab's display toggle. The backend
		// reads it on LOGIN as calibration for the sessions it stores.
		int playtime = client.getVarcIntValue(VarClientID.ACCOUNT_SUMMARY_PLAYTIME);
		if (playtime > 0) data.put("playtimeMinutes", playtime);

		return data;
	}

	private Map<String, Object> collectFullState() {
		Map<String, Object> data = new HashMap<>();
		data.put("player", playerManager.sync());
		data.put("quests", questManager.sync());
		data.put("achievementDiaries", achievementDiaryManager.sync());
		data.put("combatAchievements", combatAchievementManager.sync());
		data.put("personalBests", personalBestManager.sync());
		// Historical wire name: shared verified PBs from Collection Log and CA.
		data.put("clogPersonalBests", clogPersonalBestCapture.sync());
		return data;
	}

	/**
	 * Attach the state fingerprint (null when skipped). Seasonal worlds are
	 * skipped — leagues state is a different character.
	 */
	private String attachFingerprint(Map<String, Object> data) {
		if (Worlds.isSeasonal(client)) return null;
		String fingerprint = syncStateManager.computeFingerprint(data);
		if (fingerprint != null) {
			data.put("syncFingerprint", fingerprint);
		}
		return fingerprint;
	}
}

package com.revalclan;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

/**
 * Which game events get tracked and sent to Reval is decided by the backend
 * (see FilterManager), not by the player. The only per-player switches left
 * here are the ones that change what the player themself sees or shares.
 */
@ConfigGroup("revalclan")
public interface RevalClanConfig extends Config {

	// ── Panel Settings ─────────────────────────────────────────────────
	@ConfigSection(
		name = "Panel Settings",
		description = "Customize the Reval side panel appearance",
		position = 0
	)
	String panelSection = "panelSection";

	@ConfigItem(
		keyName = "hideCompletedItems",
		name = "Hide completed items",
		description = "Only show incomplete milestones, combat achievements and collection log tiers on the profile",
		section = panelSection,
		position = 0
	)
	default boolean hideCompletedItems() {
		return false;
	}

	// ── Events ─────────────────────────────────────────────────────────
	@ConfigSection(
		name = "Events",
		description = "Clan event features",
		position = 3
	)
	String clanEventsSection = "clanEventsSection";

	/**
	 * Keeps the old "teamNameColors" key on purpose: this used to be the single
	 * toggle for both surfaces, so anyone who had already switched colors off
	 * stays switched off for the clan list instead of having them reappear.
	 */
	@ConfigItem(
		keyName = "teamNameColors",
		name = "Team colors: clan list",
		description = "Color clan members' names by their event team in the clan member list",
		section = clanEventsSection,
		position = 0
	)
	default boolean teamColorsInClanList() {
		return true;
	}

	@ConfigItem(
		keyName = "teamColorsInChat",
		name = "Team colors: chat",
		description = "Color clan members' names by their event team in clan chat (off by default - chat is busy enough)",
		section = clanEventsSection,
		position = 1
	)
	default boolean teamColorsInChat() {
		return false;
	}

	// ── Notifications ──────────────────────────────────────────────────
	@ConfigSection(
		name = "Notifications",
		description = "What the plugin shows you in chat",
		position = 4
	)
	String eventsSection = "eventsSection";

	@ConfigItem(
		keyName = "showAnnouncements",
		name = "Show clan notifications",
		description = "Show Reval announcements and notifications in chat",
		section = eventsSection,
		position = 0
	)
	default boolean showAnnouncements() {
		return true;
	}

	@ConfigSection(
		name = "Clan browser",
		description = "Collection logs and shared clan leaderboards",
		position = 5
	)
	String clanBrowserSection = "clanBrowserSection";

	@ConfigItem(
		keyName = "enableChatCommands",
		name = "Enable !reval chat commands",
		description = "Show clickable !reval boards in public and clan chat. Turn off to leave messages as ordinary text.",
		section = clanBrowserSection,
		position = 0
	)
	default boolean enableChatCommands() {
		return true;
	}
}

