import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.inject.Inject;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;

/**
 * Highlights the path to the "Sync Reval" collection log entry while the
 * sync guide is armed: a hint banner until the collection log is open, a
 * pulsing glow on the burger menu button, then on the Sync Reval entry once
 * the menu is expanded. Each phase's hint lasts 20 seconds (a slim bar
 * drains along its bottom edge); moving to another phase restarts the
 * clock, running one out disarms the guide.
 */
public class SyncGuideOverlay extends Overlay {
	private static final Color GOLD = new Color(255, 200, 60);
	private static final long HINT_TIMEOUT_MS = 20_000;

	private final Client client;
	private final SyncGuide guide;

	private enum Phase { BANNER, BURGER, MENU }

	private Phase phase;
	private long phaseStartedAt;

	@Inject
	public SyncGuideOverlay(Client client, SyncGuide guide) {
		this.client = client;
		this.guide = guide;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D g) {
		if (!guide.isArmed()) {
			phase = null;
			return null;
		}

		Widget burger = client.getWidget(InterfaceID.Collection.BURGER_BTN_MENU);
		Widget menuFrame = client.getWidget(InterfaceID.Collection.BURGER_MENU_FRAME);
		boolean logOpen = burger != null && !burger.isHidden();
		boolean menuOpen = logOpen && menuFrame != null && !menuFrame.isHidden();
		Phase current = !logOpen ? Phase.BANNER : menuOpen ? Phase.MENU : Phase.BURGER;

		// Each phase gets its own full window; changing phase restarts the clock
		long now = System.currentTimeMillis();
		if (current != phase) {
			phase = current;
			phaseStartedAt = now;
		}
		double fraction = (double) (HINT_TIMEOUT_MS - (now - phaseStartedAt)) / HINT_TIMEOUT_MS;
		if (fraction <= 0) {
			guide.disarm();
			return null;
		}

		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		switch (current) {
			case BANNER:
				drawHint(g, "Open your Collection Log to sync your points", fraction);
				break;
			case BURGER:
				glow(g, burger.getBounds());
				drawHint(g, "Open this menu, then click Sync Reval", fraction);
				break;
			case MENU:
				Widget syncEntry = guide.getSyncButtonWidget();
				if (syncEntry != null && !syncEntry.isHidden()) {
					glow(g, syncEntry.getBounds());
					drawHint(g, "Click Sync Reval", fraction);
				} else {
					drawHint(g, "Click Sync Reval in the menu", fraction);
				}
				break;
		}
		return null;
	}

	private void glow(Graphics2D g, Rectangle bounds) {
		if (bounds == null || bounds.isEmpty()) {
			return;
		}
		// Pulse between soft and bright
		double pulse = (Math.sin(System.currentTimeMillis() / 220.0) + 1) / 2;
		int alpha = (int) (100 + pulse * 155);

		g.setColor(Colors.withAlpha(GOLD, alpha / 4));
		g.fillRoundRect(bounds.x - 3, bounds.y - 3, bounds.width + 6, bounds.height + 6, 8, 8);

		g.setStroke(new BasicStroke(2));
		g.setColor(Colors.withAlpha(GOLD, alpha));
		g.drawRoundRect(bounds.x - 3, bounds.y - 3, bounds.width + 6, bounds.height + 6, 8, 8);
	}

	/** Hint banner with a slim time bar draining along the bottom edge. */
	private void drawHint(Graphics2D g, String text, double fraction) {
		g.setFont(FontManager.getRunescapeFont());
		FontMetrics fm = g.getFontMetrics();

		int width = fm.stringWidth(text) + 24;
		int height = fm.getHeight() + 12 + 7;
		int x = (client.getCanvasWidth() - width) / 2;
		int y = 26;

		g.setColor(new Color(0, 0, 0, 180));
		g.fillRoundRect(x, y, width, height, 10, 10);
		g.setColor(Colors.withAlpha(GOLD, 140));
		g.setStroke(new BasicStroke(1));
		g.drawRoundRect(x, y, width, height, 10, 10);

		g.setColor(GOLD);
		g.drawString(text, x + 12, y + fm.getAscent() + 6);

		int trackX = x + 8;
		int trackWidth = width - 16;
		int barY = y + height - 6;
		g.setColor(new Color(255, 255, 255, 30));
		g.fillRoundRect(trackX, barY, trackWidth, 3, 3, 3);
		int fillWidth = (int) Math.round(trackWidth * Math.min(1.0, Math.max(0.0, fraction)));
		if (fillWidth > 0) {
			g.setColor(Colors.withAlpha(GOLD, 220));
			g.fillRoundRect(trackX, barY, fillWidth, 3, 3, 3);
		}
	}
}

package com.revalclan.combat;

import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.Hitsplat;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.NpcDespawned;
import net.runelite.client.game.ItemManager;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Accumulates per-kill combat details (damage, weapons, specs) from hitsplats.
 * Pure accumulator — consumers decide what a completed kill is used for
 * (session counts, DETAILED_KILL webhook), see RevalClanPlugin.onActorDeath.
 */
@Singleton
public class KillTracker {
	@Inject private Client client;
	@Inject private ItemManager itemManager;

	private final Map<NPC, KillData> activeKills = new ConcurrentHashMap<>();

	private int previousSpecEnergy = 100;
	private int specTicksRemaining = 0;
	private String specWeaponName = null;

	public void onGameTick() {
		int currentSpecEnergy = client.getVarpValue(300);

		if (currentSpecEnergy < previousSpecEnergy) {
			Player localPlayer = client.getLocalPlayer();
			if (localPlayer != null) {
				specWeaponName = equippedWeaponName(localPlayer);
				specTicksRemaining = 3;
			}
		} else if (specTicksRemaining > 0) {
			specTicksRemaining--;
			if (specTicksRemaining == 0) {
				specWeaponName = null;
			}
		}

		previousSpecEnergy = currentSpecEnergy;
	}

	public void onHitsplatApplied(HitsplatApplied event) {
		Actor actor = event.getActor();
		if (!(actor instanceof NPC)) return;

		Hitsplat hitsplat = event.getHitsplat();
		if (!hitsplat.isMine()) return;

		Player localPlayer = client.getLocalPlayer();
		if (localPlayer == null) return;

		NPC npc = (NPC) actor;
		String weaponName = equippedWeaponName(localPlayer);
		boolean isSpec = specTicksRemaining > 0 && weaponName.equals(specWeaponName);

		KillData data = activeKills.computeIfAbsent(npc, k -> new KillData(npc.getName(), npc.getId()));
		data.addHit(hitsplat.getAmount(), weaponName, isSpec);
	}

	/** Single cleanup point — death fires a despawn too. */
	public void onNpcDespawned(NpcDespawned event) {
		activeKills.remove(event.getNpc());
	}

	/** The completed kill (with damage dealt), or null when this death isn't ours. */
	public KillData onActorDeath(ActorDeath event) {
		Actor actor = event.getActor();
		if (!(actor instanceof NPC)) return null;

		KillData data = activeKills.remove((NPC) actor);
		return data != null && data.totalDamage > 0 ? data : null;
	}

	public void reset() {
		activeKills.clear();
		previousSpecEnergy = 100;
		specTicksRemaining = 0;
		specWeaponName = null;
	}

	private String equippedWeaponName(Player localPlayer) {
		int weaponId = localPlayer.getPlayerComposition().getEquipmentId(net.runelite.api.kit.KitType.WEAPON);
		return weaponId > 0 ? itemManager.getItemComposition(weaponId).getName() : "Unarmed";
	}

	public static class KillData {
		public final String npcName;
		public final int npcId;
		public int totalDamage = 0;
		public int hitCount = 0;
		public int specialAttackCount = 0;
		public String lastHitWeapon = "Unknown";
		public int lastHitDamage = 0;
		public boolean lastHitWasSpec = false;
		public final Map<String, Integer> weaponsUsed = new HashMap<>();

		KillData(String npcName, int npcId) {
			this.npcName = npcName;
			this.npcId = npcId;
		}

		void addHit(int damage, String weapon, boolean isSpec) {
			totalDamage += damage;
			hitCount++;
			lastHitWeapon = weapon;
			lastHitDamage = damage;
			lastHitWasSpec = isSpec;

			if (isSpec) {
				specialAttackCount++;
			}

			weaponsUsed.merge(weapon, damage, Integer::sum);
		}
	}
}

package com.revalclan.combatachievements;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.StructComposition;
import net.runelite.api.gameval.VarbitID;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.*;
import java.util.function.BiConsumer;

/**
 * Manages Combat Achievement task data by reading from game cache (enums/structs)
 */
@Slf4j
@Singleton
public class CombatAchievementManager {
	@Inject private Client client;

	private static final Map<Integer, String> TIER_ENUMS = new LinkedHashMap<>();
	static {
		TIER_ENUMS.put(3981, "Easy");
		TIER_ENUMS.put(3982, "Medium");
		TIER_ENUMS.put(3983, "Hard");
		TIER_ENUMS.put(3984, "Elite");
		TIER_ENUMS.put(3985, "Master");
		TIER_ENUMS.put(3986, "Grandmaster");
	}

	// Lookup only (never iterated), so an unordered map is fine
	private static final Map<Integer, String> TYPE_MAP = Map.of(
		1, "Stamina",
		2, "Perfection",
		3, "Kill Count",
		4, "Mechanical",
		5, "Restriction",
		6, "Speed"
	);


	private static final int FIELD_NAME = 1308;
	private static final int FIELD_TASK_ID = 1306;
	private static final int FIELD_TYPE_ID = 1311;

	private static final int[] COMPLETION_VARPS = {
		3116,  // CA_TASK_COMPLETED_0
		3117,  // CA_TASK_COMPLETED_1
		3118,  // CA_TASK_COMPLETED_2
		3119,  // CA_TASK_COMPLETED_3
		3120,  // CA_TASK_COMPLETED_4
		3121,  // CA_TASK_COMPLETED_5
		3122,  // CA_TASK_COMPLETED_6
		3123,  // CA_TASK_COMPLETED_7
		3124,  // CA_TASK_COMPLETED_8
		3125,  // CA_TASK_COMPLETED_9
		3126,  // CA_TASK_COMPLETED_10
		3127,  // CA_TASK_COMPLETED_11
		3128,  // CA_TASK_COMPLETED_12
		3387,  // CA_TASK_COMPLETED_13
		3718,  // CA_TASK_COMPLETED_14
		3773,  // CA_TASK_COMPLETED_15
		3774,  // CA_TASK_COMPLETED_16
		4204,  // CA_TASK_COMPLETED_17
		4496,  // CA_TASK_COMPLETED_18
		4721,  // CA_TASK_COMPLETED_19
		5673   // CA_TASK_COMPLETED_20 (task ids 640+, e.g. Maggot King — added 2026-08-12)
	};

	private final List<CombatAchievementTask> allTasks = new ArrayList<>();

	/**
	 * Sync and get combat achievement data
	 */
	public Map<String, Object> sync() {
		allTasks.clear();

		forEachTaskStruct((struct, tierName) -> {
			CombatAchievementTask task = loadTaskFromStruct(struct, tierName);
			if (task != null) allTasks.add(task);
		});

		int totalPoints = currentTotalPoints();
		Map<String, Integer> thresholds = tierThresholds();

		Map<String, Object> data = new HashMap<>();
		data.put("currentTier", calculateCurrentTier(totalPoints, thresholds));
		data.put("totalPoints", totalPoints);
		data.put("tierProgress", getTierProgress());
		data.put("tierThresholds", lowerCaseKeys(thresholds));
		data.put("allTasks", getCompletedTasks());
		data.put("totalTasksLoaded", allTasks.size());

		return data;
	}

	/** Current total CA points: the game's own varp, falling back to a task-struct sum. */
	public int currentTotalPoints() {
		int varp = readCaPointsVarbit();
		if (varp > 0) return varp;
		int[] total = {0};
		forEachTaskStruct((struct, tierName) -> {
			if (isTaskCompleted(struct.getIntValue(FIELD_TASK_ID))) {
				total[0] += getPointsForTier(tierName);
			}
		});
		return total[0];
	}

	/** Shared task-struct traversal for sync() and currentTotalPoints(). */
	private void forEachTaskStruct(BiConsumer<StructComposition, String> visitor) {
		for (Map.Entry<Integer, String> tierEntry : TIER_ENUMS.entrySet()) {
			EnumComposition tierEnum;
			try {
				tierEnum = client.getEnum(tierEntry.getKey());
			} catch (Exception e) {
				log.debug("Failed to read CA tier enum {}: {}", tierEntry.getKey(), e.getMessage());
				continue;
			}
			if (tierEnum == null) continue;

			for (int structId : tierEnum.getIntVals()) {
				try {
					StructComposition struct = client.getStructComposition(structId);
					if (struct != null) {
						visitor.accept(struct, tierEntry.getValue());
					}
				} catch (Exception e) {
					log.debug("Failed to read CA struct {}: {}", structId, e.getMessage());
				}
			}
		}
	}

	/**
	 * Loads a single task from a struct
	 */
	private CombatAchievementTask loadTaskFromStruct(StructComposition struct, String tierName) {
		CombatAchievementTask task = new CombatAchievementTask();
		task.setName(struct.getStringValue(FIELD_NAME));
		task.setTier(tierName);
		task.setType(TYPE_MAP.getOrDefault(struct.getIntValue(FIELD_TYPE_ID), "Unknown"));
		task.setCompleted(isTaskCompleted(struct.getIntValue(FIELD_TASK_ID)));
		return task;
	}

	/**
	 * Checks if a task is completed using VarPlayer
	 */
	private boolean isTaskCompleted(int taskId) {
		if (taskId < 0 || taskId >= COMPLETION_VARPS.length * 32) return false;

		int varpIndex = taskId / 32;
		int bitIndex = taskId % 32;

		try {
			int varpValue = client.getVarpValue(COMPLETION_VARPS[varpIndex]);
			return (varpValue & (1 << bitIndex)) != 0;
		} catch (Exception e) {
			return false;
		}
	}

	/**
	 * Gets points for a tier
	 */
	private int getPointsForTier(String tier) {
		switch (tier.toLowerCase()) {
			case "easy": return 1;
			case "medium": return 2;
			case "hard": return 3;
			case "elite": return 4;
			case "master": return 5;
			case "grandmaster": return 6;
			default: return 1;
		}
	}

	/**
	 * The game's own CA points counter — authoritative, and immune to Jagex
	 * adding new completion varps with new task batches (which silently broke
	 * the per-task sum when task ids passed 640). Returns 0 when the varbit
	 * is unavailable so callers can fall back to summing completed tasks.
	 */
	private int readCaPointsVarbit() {
		try {
			return client.getVarbitValue(VarbitID.CA_POINTS);
		} catch (Exception e) {
			return 0;
		}
	}

	/** The game's own per-tier unlock points, in ladder order (packed into varps CA_THRESHOLDS1-3). */
	private static final int[] THRESHOLD_VARBITS = {
		VarbitID.CA_THRESHOLD_EASY,
		VarbitID.CA_THRESHOLD_MEDIUM,
		VarbitID.CA_THRESHOLD_HARD,
		VarbitID.CA_THRESHOLD_ELITE,
		VarbitID.CA_THRESHOLD_MASTER,
		VarbitID.CA_THRESHOLD_GRANDMASTER
	};

	/**
	 * Points needed to unlock each tier, read from the game's CA_THRESHOLD_* varbits
	 * so a new task batch is reflected the moment it goes live, with no plugin release.
	 * Returns an empty map (=> currentTier "None") if the varps haven't arrived, which
	 * only happens when the rest of the CA varps are missing too and the sync is moot.
	 */
	private Map<String, Integer> tierThresholds() {
		Map<String, Integer> thresholds = new LinkedHashMap<>();
		int previous = 0;
		int i = 0;
		for (String tier : TIER_ENUMS.values()) {
			int value = client.getVarbitValue(THRESHOLD_VARBITS[i++]);
			if (value <= previous) {
				log.warn("CA tier thresholds not available from varbits ({} = {})", tier, value);
				return Collections.emptyMap();
			}
			thresholds.put(tier, value);
			previous = value;
		}
		return thresholds;
	}

	/** The game's tier ladder with lowercase keys, for event payloads; empty if the varps aren't in yet. */
	public Map<String, Integer> tierThresholdsForPayload() {
		return lowerCaseKeys(tierThresholds());
	}

	/** Highest tier whose unlock point the player has reached, walking the ladder in order. */
	private String calculateCurrentTier(int totalPoints, Map<String, Integer> thresholds) {
		String current = "None";
		for (Map.Entry<String, Integer> tier : thresholds.entrySet()) {
			if (totalPoints < tier.getValue()) break;
			current = tier.getKey();
		}
		return current;
	}

	private static Map<String, Integer> lowerCaseKeys(Map<String, Integer> map) {
		Map<String, Integer> out = new LinkedHashMap<>();
		map.forEach((k, v) -> out.put(k.toLowerCase(), v));
		return out;
	}

	/**
	 * Get tier progress breakdown
	 */
	private Map<String, Map<String, Integer>> getTierProgress() {
		Map<String, Map<String, Integer>> tierProgress = new LinkedHashMap<>();

		for (String tier : TIER_ENUMS.values()) {
			int completed = (int) allTasks.stream()
				.filter(t -> t.getTier().equals(tier) && t.isCompleted())
				.count();

			int total = (int) allTasks.stream()
				.filter(t -> t.getTier().equals(tier))
				.count();

			Map<String, Integer> tierData = new HashMap<>();
			tierData.put("completed", completed);
			tierData.put("total", total);
			tierProgress.put(tier.toLowerCase(), tierData);
		}

		return tierProgress;
	}

	/** Only COMPLETED tasks. The server's storage path filters on the completed flag. */
	private List<Map<String, Object>> getCompletedTasks() {
		List<Map<String, Object>> tasksList = new ArrayList<>();

		for (CombatAchievementTask task : allTasks) {
			if (!task.isCompleted()) continue;
			tasksList.add(Map.of(
				"name", task.getName(),
				"tier", task.getTier(),
				"type", task.getType(),
				"completed", true
			));
		}

		return tasksList;
	}
}

