import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

@Singleton
public class LeaguesNotifier extends BaseNotifier {
	private static final String AREA_UNLOCK_PREFIX = "Congratulations, you've unlocked a new area: ";
	private static final String RELIC_UNLOCK_PREFIX = "Congratulations, you've unlocked a new Relic: ";
	private static final Pattern TASK_PATTERN = Pattern.compile(
		"Congratulations, you've completed an? (?<tier>\\w+) task: (?<task>.+?)\\."
	);
	private static final Pattern MASTERY_PATTERN = Pattern.compile(
		"Congratulations, you've unlocked a new .+ Combat Mastery: (?<type>\\w+) (?<tier>\\w+)\\."
	);

	private static final Map<String, Integer> ROMAN_NUMERALS = Map.of(
		"I", 1, "II", 2, "III", 3, "IV", 4, "V", 5, "VI", 6, "VII", 7, "VIII", 8, "IX", 9, "X", 10
	);

	private static final int CONFIG_RETRY_INTERVAL = 100;
	private static final int CONFIG_MAX_RETRIES = 5;

	@Inject private RevalApiService revalApiService;

	private String currentEventType = "LEAGUES";

	private TreeMap<Integer, String> pointsToTrophy = new TreeMap<>();
	private TreeMap<Integer, Integer> pointsToRelicTier = new TreeMap<>();
	private Map<String, Integer> relicNameToTier = new HashMap<>();
	private Map<String, Integer> difficultyToPoints = new HashMap<>();
	private List<Integer> areaUnlockTasks;

	private int configRetryTicks = 0;
	private int configRetryAttempts = 0;

	@Override
	public boolean isEnabled() {
		return filterManager.getFilters().isLeaguesEnabled()
			&& Worlds.isSeasonal(client);
	}

	private boolean hasConfig() {
		LeaguesConfigResponse.LeaguesConfig cfg = revalApiService.getCachedLeaguesConfig();
		return cfg != null
			&& cfg.getLeagueVersion() == client.getVarbitValue(VarbitID.LEAGUE_TYPE);
	}

	@Override
	protected String getEventType() {
		return currentEventType;
	}

	public void onGameTick() {
		if (revalApiService.getCachedLeaguesConfig() != null || configRetryAttempts >= CONFIG_MAX_RETRIES) return;
		if (!Worlds.isSeasonal(client)) return;

		configRetryTicks++;
		if (configRetryTicks >= CONFIG_RETRY_INTERVAL) {
			configRetryTicks = 0;
			configRetryAttempts++;
			fetchConfig();
		}
	}

	public void fetchConfig() {
		revalApiService.fetchLeaguesConfig(
			this::buildLookupMaps,
			error -> {}
		);
	}

	public void reset() {
		configRetryTicks = 0;
		configRetryAttempts = 0;
		revalApiService.clearLeaguesCache();
	}

	public void onChatMessage(String message) {
		if (!isEnabled()) return;

		if (message.startsWith(AREA_UNLOCK_PREFIX)) {
			notifyAreaUnlock(message.substring(AREA_UNLOCK_PREFIX.length(), message.length() - 1));
			return;
		}

		if (message.startsWith(RELIC_UNLOCK_PREFIX)) {
			notifyRelicUnlock(message.substring(RELIC_UNLOCK_PREFIX.length(), message.length() - 1));
			return;
		}

		Matcher taskMatcher = TASK_PATTERN.matcher(message);
		if (taskMatcher.find()) {
			notifyTaskCompletion(taskMatcher.group("tier"), taskMatcher.group("task"));
			return;
		}

		Matcher masteryMatcher = MASTERY_PATTERN.matcher(message);
		if (masteryMatcher.find()) {
			notifyCombatMastery(masteryMatcher.group("type"), masteryMatcher.group("tier"));
		}
	}

	private void notifyTaskCompletion(String tierName, String taskName) {
		int totalPoints = client.getVarpValue(VarPlayerID.LEAGUE_POINTS_COMPLETED);
		int tasksCompleted = client.getVarbitValue(VarbitID.LEAGUE_TOTAL_TASKS_COMPLETED);

		currentEventType = "LEAGUES_TASK";
		Map<String, Object> data = createBaseData();
		data.put("taskName", taskName);
		data.put("difficultyTier", tierName);
		data.put("totalPoints", totalPoints);
		data.put("tasksCompleted", tasksCompleted);

		if (hasConfig()) {
			int taskPoints = difficultyToPoints.getOrDefault(tierName.toLowerCase(), 0);

			String trophyEarned = null;
			Map.Entry<Integer, String> currentTrophy = pointsToTrophy.floorEntry(totalPoints);
			if (currentTrophy != null) {
				Map.Entry<Integer, String> previousTrophy = pointsToTrophy.floorEntry(totalPoints - taskPoints);
				if (previousTrophy == null || currentTrophy.getKey() > previousTrophy.getKey()) {
					trophyEarned = currentTrophy.getValue();
				}
			}

			data.put("taskPoints", taskPoints);
			data.put("tasksUntilNextArea", computeTasksUntilNextArea(tasksCompleted));
			data.put("pointsUntilNextRelic", pointsUntilNext(pointsToRelicTier, totalPoints));
			data.put("pointsUntilNextTrophy", pointsUntilNext(pointsToTrophy, totalPoints));
			data.put("trophyEarned", trophyEarned);
		}

		sendNotification(data);
	}

	private void notifyRelicUnlock(String relicName) {
		int currentPoints = client.getVarpValue(VarPlayerID.LEAGUE_POINTS_COMPLETED);

		currentEventType = "LEAGUES_RELIC";
		Map<String, Object> data = createBaseData();
		data.put("relicName", relicName);
		data.put("currentPoints", currentPoints);

		if (hasConfig()) {
			Integer relicTier = relicNameToTier.getOrDefault(relicName, 0);
			int requiredPoints = 0;
			for (Map.Entry<Integer, Integer> entry : pointsToRelicTier.entrySet()) {
				if (entry.getValue().equals(relicTier)) {
					requiredPoints = entry.getKey();
					break;
				}
			}

			data.put("relicTier", relicTier);
			data.put("requiredPoints", requiredPoints);
			data.put("pointsUntilNextTier", pointsUntilNext(pointsToRelicTier, currentPoints));
		}

		sendNotification(data);
	}

	private void notifyAreaUnlock(String areaName) {
		int tasksCompleted = client.getVarbitValue(VarbitID.LEAGUE_TOTAL_TASKS_COMPLETED);

		currentEventType = "LEAGUES_AREA";
		Map<String, Object> data = createBaseData();
		data.put("areaName", areaName);
		data.put("areaIndex", computeAreasUnlocked());
		data.put("tasksCompleted", tasksCompleted);

		if (hasConfig()) {
			data.put("tasksUntilNextArea", computeTasksUntilNextArea(tasksCompleted));
		}

		sendNotification(data);
	}

	private void notifyCombatMastery(String type, String romanTier) {
		Integer tier = ROMAN_NUMERALS.get(romanTier);
		if (tier == null) return;

		currentEventType = "LEAGUES_MASTERY";
		Map<String, Object> data = createBaseData();
		data.put("masteryType", type);
		data.put("masteryTier", tier);

		sendNotification(data);
	}

	private Map<String, Object> createBaseData() {
		Map<String, Object> data = new HashMap<>();
		data.put("seasonalWorld", true);
		LeaguesConfigResponse.LeaguesConfig cfg = revalApiService.getCachedLeaguesConfig();
		if (cfg != null) {
			data.put("leagueName", cfg.getLeagueName());
		}
		return data;
	}

	private int computeAreasUnlocked() {
		try {
			if (client.getVarbitValue(VarbitID.LEAGUE_AREA_SELECTION_4) > 0) return 3;
			if (client.getVarbitValue(VarbitID.LEAGUE_AREA_SELECTION_3) > 0) return 2;
			if (client.getVarbitValue(VarbitID.LEAGUE_AREA_SELECTION_2) > 0) return 1;
			if (client.getVarbitValue(VarbitID.LEAGUE_AREA_SELECTION_1) > 0) return 0;
		} catch (Exception e) {
			// Area selection varbits not available, use task-based fallback
		}

		if (areaUnlockTasks != null) {
			int tasksCompleted = client.getVarbitValue(VarbitID.LEAGUE_TOTAL_TASKS_COMPLETED);
			int unlocked = 0;
			for (int threshold : areaUnlockTasks) {
				if (tasksCompleted >= threshold) unlocked++;
			}
			return unlocked;
		}

		return 0;
	}

	/** Points from {@code points} to the next threshold above it, or null when none is left. */
	private static Integer pointsUntilNext(TreeMap<Integer, ?> thresholds, int points) {
		Integer next = thresholds.ceilingKey(points + 1);
		return next != null ? next - points : null;
	}

	private Integer computeTasksUntilNextArea(int tasksCompleted) {
		if (areaUnlockTasks == null) return null;
		for (int threshold : areaUnlockTasks) {
			if (tasksCompleted < threshold) return threshold - tasksCompleted;
		}
		return null;
	}

	private void buildLookupMaps(LeaguesConfigResponse.LeaguesConfig cfg) {
		pointsToTrophy.clear();
		for (LeaguesConfigResponse.Trophy trophy : cfg.getTrophies()) {
			pointsToTrophy.put(trophy.getPointsRequired(), trophy.getName());
		}

		pointsToRelicTier.clear();
		relicNameToTier.clear();
		for (LeaguesConfigResponse.RelicTier tier : cfg.getRelicTiers()) {
			pointsToRelicTier.put(tier.getPointsRequired(), tier.getTier());
			for (String relicName : tier.getRelics()) {
				relicNameToTier.put(relicName, tier.getTier());
			}
		}

		difficultyToPoints.clear();
		for (LeaguesConfigResponse.TaskDifficulty diff : cfg.getTaskDifficulties()) {
			difficultyToPoints.put(diff.getName().toLowerCase(), diff.getPoints());
		}

		areaUnlockTasks = cfg.getAreaUnlockTasks();
	}
}

package com.revalclan.notifiers;

import com.revalclan.util.Worlds;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;

import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Leagues panel sync notifier.
 * Sends LEAGUES_SYNC on login and when the Relics modal is opened.
 * Payload: leagueType, totalPoints, tasksCompleted, areaSelections (id + name),
 * and selectedRelics (when available from Relics modal).
 */
@Singleton
public class LeaguesSyncNotifier extends BaseNotifier {

	private static final int LEAGUES_RELICS_GROUP = 655;
	private static final int RELIC_READ_DELAY_TICKS = 2;
	private static final int RELIC_SELECTED_COLOR = 0xF47113;
	private static final int RELIC_UNSELECTED_COLOR = 0xAAAAAA;

	private static final Map<Integer, String> AREA_NAMES = Map.of(
		2, "Karamja",
		7, "Tirannwn",
		21, "Varlamore"
	);

	private List<String> cachedSelectedRelics = null;
	/** Ticks until the opened Relics modal is read; 0 when no read is pending. */
	private int pendingRelicTicks = 0;

	@Override
	public boolean isEnabled() {
		return Worlds.isSeasonal(client);
	}

	@Override
	protected String getEventType() {
		return "LEAGUES_SYNC";
	}

	/**
	 * Called after login on a seasonal world. Sends initial sync.
	 */
	public void onLogin() {
		if (!isEnabled()) return;
		sendSync();
	}

	public void onWidgetLoaded(WidgetLoaded event) {
		if (!isEnabled() || event.getGroupId() != LEAGUES_RELICS_GROUP) return;
		pendingRelicTicks = RELIC_READ_DELAY_TICKS;
	}

	public void onGameTick() {
		if (pendingRelicTicks == 0) return;
		if (--pendingRelicTicks > 0) return;

		List<String> relics = extractRelics();
		if (!relics.isEmpty()) {
			cachedSelectedRelics = relics;
			sendSync();
		}
	}

	public void reset() {
		pendingRelicTicks = 0;
		cachedSelectedRelics = null;
	}

	// ========== Payload ==========

	private void sendSync() {
		Map<String, Object> data = new HashMap<>();
		data.put("seasonalWorld", true);
		data.put("leagueType", client.getVarbitValue(VarbitID.LEAGUE_TYPE));
		data.put("totalPoints", client.getVarpValue(VarPlayerID.LEAGUE_POINTS_COMPLETED));
		data.put("tasksCompleted", client.getVarbitValue(VarbitID.LEAGUE_TOTAL_TASKS_COMPLETED));

		List<Map<String, Object>> areas = new ArrayList<>();
		for (int areaId : new int[]{
			client.getVarbitValue(VarbitID.LEAGUE_AREA_SELECTION_0),
			client.getVarbitValue(VarbitID.LEAGUE_AREA_SELECTION_1),
			client.getVarbitValue(VarbitID.LEAGUE_AREA_SELECTION_2),
			client.getVarbitValue(VarbitID.LEAGUE_AREA_SELECTION_3),
			client.getVarbitValue(VarbitID.LEAGUE_AREA_SELECTION_4),
			client.getVarbitValue(VarbitID.LEAGUE_AREA_SELECTION_5)
		}) {
			if (areaId != 0) {
				Map<String, Object> area = new HashMap<>();
				area.put("id", areaId);
				area.put("name", AREA_NAMES.getOrDefault(areaId, "Unknown"));
				areas.add(area);
			}
		}
		data.put("areaSelections", areas);

		if (cachedSelectedRelics != null && !cachedSelectedRelics.isEmpty()) {
			data.put("selectedRelics", cachedSelectedRelics);
		}

		sendNotification(data);
	}

	// ========== Relics ==========

	private List<String> extractRelics() {
		List<String> selected = new ArrayList<>();
		for (int childId = 0; childId < 20; childId++) {
			Widget child = client.getWidget(LEAGUES_RELICS_GROUP, childId);
			if (child == null) continue;
			if (collectSelectedRelics(child, selected, 0)) break;
		}
		return selected;
	}

	private boolean collectSelectedRelics(Widget widget, List<String> selected, int depth) {
		if (widget == null || depth > 8) return false;

		Widget[] dc = widget.getDynamicChildren();
		if (dc != null && dc.length == 23 && dc[0] != null && dc[0].getType() == 4) {
			boolean hasOrange = false, hasGrey = false;
			for (Widget w : dc) {
				if (w == null) continue;
				if (w.getTextColor() == RELIC_SELECTED_COLOR) hasOrange = true;
				if (w.getTextColor() == RELIC_UNSELECTED_COLOR) hasGrey = true;
			}

			if (hasOrange && hasGrey) {
				// Relics are listed three per tier (the last tier has two)
				for (int tierStart = 0; tierStart < dc.length; tierStart += 3) {
					String orangeRelic = null;
					boolean hasGreyInTier = false;
					for (int idx = tierStart; idx < Math.min(tierStart + 3, dc.length); idx++) {
						if (dc[idx] == null) continue;
						if (dc[idx].getTextColor() == RELIC_SELECTED_COLOR) {
							orangeRelic = dc[idx].getText();
						} else if (dc[idx].getTextColor() == RELIC_UNSELECTED_COLOR) {
							hasGreyInTier = true;
						}
					}
					if (orangeRelic != null && hasGreyInTier) {
						selected.add(orangeRelic);
					}
				}
				return true;
			}
		}

		Widget[] sc = widget.getStaticChildren();
		if (sc != null) {
			for (Widget child : sc) {
				if (collectSelectedRelics(child, selected, depth + 1)) return true;
			}
		}
		if (dc != null) {
			for (Widget child : dc) {
				if (collectSelectedRelics(child, selected, depth + 1)) return true;
			}
		}
		return false;
	}
}

package com.revalclan.notifiers;

import net.runelite.api.Skill;
import net.runelite.api.events.StatChanged;

import javax.inject.Singleton;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.Map;

/**
 * Notifies on level ups
 */
@Singleton
public class LevelNotifier extends BaseNotifier {
	private final Map<Skill, Integer> previousLevels = new EnumMap<>(Skill.class);
	private final Map<Skill, Integer> previousXp = new EnumMap<>(Skill.class);

	@Override
	public boolean isEnabled() {
		return filterManager.getFilters().isLevelEnabled();
	}

	@Override
	protected String getEventType() {
		return "LEVEL";
	}

	public void onStatChanged(StatChanged event) {
		if (!isEnabled()) return;

		Skill skill = event.getSkill();
		int newLevel = event.getLevel();
		int newXp = event.getXp();

		// Update tracking; the first sighting of a skill only initializes it
		Integer oldLevel = previousLevels.put(skill, newLevel);
		Integer oldXp = previousXp.put(skill, newXp);

		// Check for level up
		if (oldLevel != null && newLevel > oldLevel && newXp > oldXp) {
			handleLevelUp(skill, newLevel, newXp);
		}
	}

	private void handleLevelUp(Skill skill, int level, int xp) {
		int totalLevel = client.getTotalLevel();
		long totalXp = client.getOverallExperience();
		int combatLevel = client.getLocalPlayer() != null ? client.getLocalPlayer().getCombatLevel() : 0;

		Map<String, Object> levelData = new HashMap<>();
		levelData.put("skill", skill.getName());
		levelData.put("level", level);
		levelData.put("experience", xp);
		levelData.put("totalLevel", totalLevel);
		levelData.put("totalExperience", totalXp);
		levelData.put("combatLevel", combatLevel);

		sendNotification(levelData);
	}

	public void reset() {
		previousLevels.clear();
		previousXp.clear();
	}
}

package com.revalclan.notifiers;

import javax.inject.Singleton;

import com.google.inject.Inject;
import com.revalclan.PlayerDataCollector;
import com.revalclan.util.SyncStateManager;

import java.util.Map;
import java.util.function.Consumer;
import com.google.gson.JsonObject;

/**
 * Sends the LOGIN boundary payload (full or slim depending on the fingerprint).
 */
@Singleton
public class LoginNotifier extends BaseNotifier {
	@Inject
	private PlayerDataCollector dataCollector;

	@Inject
	private SyncStateManager syncStateManager;

	@Override
	public boolean isEnabled() {
		return true;
	}

	@Override
	protected String getEventType() {
		return "LOGIN";
	}

	/**
	 * Called when the player logs in.
	 */
	public void onLogin(Consumer<JsonObject> onChanges) {
		Map<String, Object> data = dataCollector.collectBoundaryData();
		Consumer<JsonObject> ack = syncStateManager.ackHandler(client.getAccountHash());
		sendNotification(data, response -> {
			ack.accept(response);
			onChanges.accept(response);
		});
	}
}

package com.revalclan.notifiers;

import java.util.Map;

import javax.inject.Inject;
import javax.inject.Singleton;

import com.revalclan.PlayerDataCollector;
import com.revalclan.session.SessionTracker;
import com.revalclan.util.SyncStateManager;

/**
 * Sends the LOGOUT boundary payload plus the session summary accumulated since login.
 */
@Singleton
public class LogoutNotifier extends BaseNotifier {
	@Inject
	private PlayerDataCollector dataCollector;

	@Inject
	private SyncStateManager syncStateManager;

	@Inject
	private SessionTracker sessionTracker;

	@Override
	public boolean isEnabled() {
		return true;
	}

	@Override
	protected String getEventType() {
		return "LOGOUT";
	}

	/** The membership cache is reset on the login screen where LOGOUT fires; RevalClanPlugin gates on the previous answer. */
	@Override
	protected boolean passesClanCheck() {
		return true;
	}

	/** @param sessionSummary Finalized summary from SessionTracker (nullable) */
	public void onLogout(Map<String, Object> sessionSummary) {
		Map<String, Object> data = dataCollector.collectBoundaryData();
		if (sessionSummary != null) {
			data.put("sessionSummary", sessionSummary);
		}
		String sessionId = sessionSummary != null ? (String) sessionSummary.get("sessionId") : null;
		sendNotification(data, syncStateManager.ackHandler(client.getAccountHash())
			.andThen(response -> sessionTracker.confirmDelivered(sessionId, response)));
	}
}

