/** Rounded card with a left accent bar, stacking its children vertically; optionally hover-highlighted. */
public class AccentCard extends JPanel {
	private final Color accent;
	private final boolean hoverable;
	private boolean hovered;
	private boolean dim;

	public AccentCard(Color accent, boolean hoverable) {
		this.accent = accent;
		this.hoverable = hoverable;
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setOpaque(false);
		setBorder(new EmptyBorder(9, 14, 9, 10));
		setAlignmentX(Component.LEFT_ALIGNMENT);
	}

	public void setHovered(boolean hovered) {
		this.hovered = hoverable && hovered;
		repaint();
	}

	/** Fades the accent bar, for cards describing something locked. */
	public void setDim(boolean dim) {
		this.dim = dim;
	}

	@Override
	public Dimension getMaximumSize() {
		return new Dimension(Integer.MAX_VALUE, super.getPreferredSize().height);
	}

	@Override
	protected void paintComponent(Graphics g) {
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g2.setColor(hovered ? UIConstants.CARD_HOVER : UIConstants.CARD_BG);
		g2.fill(new RoundRectangle2D.Float(0, 0, getWidth(), getHeight(), 10, 10));
		g2.setColor(UIConstants.BORDER_COLOR);
		g2.draw(new RoundRectangle2D.Float(0.5f, 0.5f, getWidth() - 1, getHeight() - 1, 10, 10));
		g2.setColor(dim ? Colors.withAlpha(accent, 90) : accent);
		g2.fillRoundRect(0, 6, 4, getHeight() - 12, 4, 4);
		g2.dispose();
	}
}

package com.revalclan.ui.components;

import com.revalclan.ui.constants.UIConstants;

import javax.swing.*;
import java.awt.*;
import java.awt.geom.Path2D;
import java.awt.geom.RoundRectangle2D;

/**
 * Small header button that shows a lock icon.
 * Gold background when admin, dark/muted when not.
 */
public class AdminButton extends JButton {
	private boolean isAdmin = false;

	public AdminButton() {
		setPreferredSize(new Dimension(22, 22));
		setMaximumSize(new Dimension(22, 22));
		setMinimumSize(new Dimension(22, 22));
		setContentAreaFilled(false);
		setBorderPainted(false);
		setFocusPainted(false);
		setEnabled(false);
	}

	public void setAdmin(boolean admin) {
		this.isAdmin = admin;
		setEnabled(admin);
		setCursor(admin ? Cursor.getPredefinedCursor(Cursor.HAND_CURSOR) : Cursor.getDefaultCursor());
		setToolTipText(admin ? "Admin" : null);
		repaint();
	}

	@Override
	protected void paintComponent(Graphics g) {
		Graphics2D g2d = (Graphics2D) g.create();
		g2d.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		int w = getWidth();
		int h = getHeight();

		// Background
		g2d.setColor(!isAdmin ? UIConstants.CARD_BG
			: getModel().isPressed() ? UIConstants.ACCENT_GOLD.darker()
			: getModel().isRollover() ? UIConstants.ACCENT_GOLD.brighter()
			: UIConstants.ACCENT_GOLD);
		g2d.fillRoundRect(0, 0, w, h, 6, 6);

		// Lock icon — scale to fit within the button
		float s = w / 22f;
		g2d.setColor(isAdmin ? Color.BLACK : UIConstants.TEXT_MUTED);
		g2d.setStroke(new BasicStroke(1.6f * s, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));

		// Body (rounded rect)
		g2d.draw(new RoundRectangle2D.Float(6 * s, 10 * s, 10 * s, 8 * s, 2 * s, 2 * s));

		// Shackle (arc on top)
		Path2D shackle = new Path2D.Float();
		shackle.moveTo(8 * s, 10 * s);
		shackle.curveTo(8 * s, 6 * s, 11 * s, 4 * s, 11 * s, 4 * s);
		shackle.curveTo(11 * s, 4 * s, 14 * s, 4 * s, 14 * s, 10 * s);
		g2d.draw(shackle);

		g2d.dispose();
	}
}

package com.revalclan.ui.components;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;

/**
 * Right-pointing arrow drawn in code — the RuneScape font has no "→" glyph,
 * which rendered as a missing-glyph box on macOS.
 */
public class ArrowIcon extends PaintedIcon {
	public ArrowIcon(int size, Color color) {
		super(size, color);
	}

	@Override
	void paint(Graphics2D g2d, int x, int y) {
		g2d.setStroke(new BasicStroke(1.6f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));

		int midY = y + size / 2;
		int x0 = x + 1;
		int x1 = x + size - 2;
		int head = Math.max(3, size / 3);

		g2d.drawLine(x0, midY, x1, midY);
		g2d.drawLine(x1 - head, midY - head, x1, midY);
		g2d.drawLine(x1 - head, midY + head, x1, midY);
	}
}

