import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.awt.Insets;
import java.awt.RenderingHints;
import java.awt.geom.RoundRectangle2D;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;

/** The lettered tile grid of one board for one team; a finished board gets an accent frame. */
final class BoardGridView extends JPanel {
	private static final int GAP = 4;
	private static final int GUTTER = 16;
	private static final int PANEL_WIDTH = 198;

	private final List<TileCell> cells = new ArrayList<>();

	BoardGridView(Payload payload, Team team, Board board, LeaguesRegions.Region meta, BoardStats stats,
				  TileIcons icons, String selectedTileId, Consumer<Tile> onSelect) {
		super(new FlowLayout(FlowLayout.CENTER, 0, 0));
		setOpaque(false);
		setAlignmentX(Component.LEFT_ALIGNMENT);

		int cols = Math.max(1, board.getColumns());
		int rows = Math.max(1, board.getRows());
		int tileSize = Math.max(14, Math.min(56, (PANEL_WIDTH - GUTTER - (cols - 1) * GAP) / cols));

		JPanel grid = new JPanel(new GridBagLayout()) {
			@Override
			protected void paintComponent(Graphics g) {
				super.paintComponent(g);
				if (!stats.isBoardComplete()) return;
				Graphics2D g2 = (Graphics2D) g.create();
				g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				g2.setColor(Colors.withAlpha(meta.getAccent(), 110));
				g2.setStroke(new BasicStroke(1.5f));
				g2.draw(new RoundRectangle2D.Float(GUTTER - 2, GUTTER - 2, getWidth() - GUTTER + 1, getHeight() - GUTTER + 1, 10, 10));
				g2.dispose();
			}
		};
		grid.setOpaque(false);
		GridBagConstraints c = new GridBagConstraints();
		c.insets = new Insets(GAP / 2, GAP / 2, GAP / 2, GAP / 2);

		for (int col = 0; col < cols; col++) {
			c.gridx = col + 1;
			c.gridy = 0;
			grid.add(gutterLabel(String.valueOf((char) ('A' + col)), tileSize, GUTTER - GAP), c);
		}

		Color accent = LeaguesBingoPanel.teamColor(team);
		for (int r = 0; r < rows; r++) {
			c.gridx = 0;
			c.gridy = r + 1;
			grid.add(gutterLabel(String.valueOf(r + 1), GUTTER - GAP, tileSize), c);

			for (int col = 0; col < cols; col++) {
				c.gridx = col + 1;
				String position = String.valueOf((char) ('A' + col)) + (r + 1);
				Tile tile = payload.isTilesHidden() ? null : board.tileAt(position);

				TileCell cell;
				if (tile == null) {
					// A lock while the tiles are hidden, filler for an empty position.
					cell = new TileCell(null, payload.isTilesHidden() ? TileCell.State.HIDDEN : TileCell.State.FILLER,
						0, meta.getAccent(), tileSize);
				} else {
					int percent = BoardStats.tilePercent(team, tile);
					TileCell.State state = percent >= 100 ? TileCell.State.COMPLETED
						: percent > 0 ? TileCell.State.IN_PROGRESS : TileCell.State.NOT_STARTED;
					cell = new TileCell(tile, state, percent, accent, tileSize);
					cell.setDimmed(stats.isLocked());
					cell.setSelected(tile.getBoardTileId().equals(selectedTileId));
					cells.add(cell);
					Clickable.onPress(cell, () -> onSelect.accept(tile), cell::setHovered);
					icons.load(tile, cell);
				}
				grid.add(cell, c);
			}
		}
		add(grid);
	}

	void setSelected(String tileId) {
		for (TileCell c : cells) {
			c.setSelected(c.getTile().getBoardTileId().equals(tileId));
		}
	}

	private static JLabel gutterLabel(String text, int width, int height) {
		JLabel l = Labels.small(text, UIConstants.TEXT_MUTED);
		l.setHorizontalAlignment(JLabel.CENTER);
		l.setPreferredSize(new Dimension(width, height));
		return l;
	}
}

package com.revalclan.ui.leaguesbingo;

import com.revalclan.api.leaguesbingo.LeaguesBingoResponse.Board;
import com.revalclan.api.leaguesbingo.LeaguesBingoResponse.Team;
import com.revalclan.api.leaguesbingo.LeaguesBingoResponse.Tile;
import com.revalclan.api.leaguesbingo.LeaguesBingoResponse.TileProgress;
import com.revalclan.api.leaguesbingo.LeaguesBingoResponse.UnlockedRegion;
import lombok.AccessLevel;
import lombok.AllArgsConstructor;
import lombok.Getter;

/** One team's standing on one region board, derived from the public payload. */
@Getter
@AllArgsConstructor(access = AccessLevel.PRIVATE)
public final class BoardStats {
	/** A started-but-tiny progress still gets a visible sliver on tiles and bars. */
	public static final int MIN_VISIBLE_PERCENT = 8;

	private final int total;
	private final int completed;
	private final int earned;
	private final int bonus;
	private final boolean locked;
	private final boolean boardComplete;

	public static BoardStats of(Team team, Board board) {
		UnlockedRegion unlock = team.unlockFor(board.getRegion());
		int completed = 0;
		int earned = 0;
		for (Tile t : board.getTiles()) {
			if (team.completionFor(t.getBoardTileId()) != null) {
				completed++;
				earned += t.getPoints();
			}
		}
		return new BoardStats(
			board.getTiles().size(), completed, earned,
			unlock != null && unlock.getBonusPoints() != null ? unlock.getBonusPoints() : 0,
			unlock == null,
			unlock != null && unlock.getBoardCompletedAt() != null);
	}

	public int percent() {
		return total == 0 ? 0 : (int) Math.round(100d * completed / total);
	}

	public boolean allDone() {
		return total > 0 && completed == total;
	}

	/** "5/9 tiles  |  12 + 19/19 pts", or the board's shape while tiles are hidden. */
	public String line(Board board) {
		if (board.getTiles().isEmpty()) {
			return board.getRows() + "x" + board.getColumns() + " board  |  tiles hidden";
		}
		return completed + "/" + total + " tiles  |  " + earned + (bonus > 0 ? " + " + bonus : "") + "/" + board.getTotalPoints() + " pts";
	}

	/** 100 when done, MIN_VISIBLE_PERCENT..99 while in progress, 0 when untouched. */
	public static int tilePercent(Team team, Tile tile) {
		if (team.completionFor(tile.getBoardTileId()) != null) return 100;
		TileProgress p = team.progressFor(tile.getBoardTileId());
		if (p == null) return 0;
		double value = p.getValue() != null ? p.getValue() : 0;
		int total = p.getTotalRequirements() != null ? p.getTotalRequirements() : 0;
		int pct;
		if (total > 1) {
			pct = (int) Math.round(100d * p.completedRequirementCount() / total);
		} else if (p.getTarget() != null && p.getTarget() > 0) {
			pct = (int) Math.round(100d * value / p.getTarget());
		} else {
			pct = 0;
		}
		if (pct <= 0 && value > 0) pct = MIN_VISIBLE_PERCENT;
		return Math.max(0, Math.min(99, pct));
	}
}

