/** The event summary, the standings rows and the team chip above the boards. */
final class TeamCards {
	private static final int NAME_WIDTH = 112;

	private TeamCards() {
	}

	static JComponent eventSummary(Payload payload) {
		AccentCard card = new AccentCard(UIConstants.ACCENT_GREEN, false);
		String status = payload.getEvent() != null ? payload.getEvent().getStatus() : null;
		boolean live = "active".equalsIgnoreCase(status);

		JPanel top = Labels.row();
		top.add(new Badge(live ? "LIVE" : status != null ? status.toUpperCase() : "EVENT", live ? UIConstants.ACCENT_GREEN : UIConstants.TEXT_SECONDARY), BorderLayout.WEST);
		top.add(Labels.small(payload.getTeams().size() + " teams", UIConstants.TEXT_SECONDARY), BorderLayout.EAST);
		card.add(top);

		String endDate = payload.getEvent() != null ? payload.getEvent().getEndDate() : null;
		if (endDate != null) {
			card.add(Box.createVerticalStrut(6));
			card.add(Labels.small((live ? "Ends " : "Ended ") + DateTimeUtil.formatShort(endDate), UIConstants.TEXT_MUTED));
		}
		if (payload.isTilesHidden()) {
			card.add(Box.createVerticalStrut(6));
			String reveal = payload.getTilesRevealAt() != null ? "Tiles reveal " + DateTimeUtil.formatShort(payload.getTilesRevealAt()) : "Tiles not revealed yet";
			card.add(Labels.small(reveal, UIConstants.ACCENT_GOLD));
		}
		return card;
	}

	/** Standings row: rank, name, YOU badge, score, and the tiles / regions / x2 line. */
	static JComponent row(Team team, int rank, boolean mine, Runnable onOpen) {
		Color color = LeaguesBingoPanel.teamColor(team);
		AccentCard card = new AccentCard(color, true);

		JPanel top = Labels.row();
		JPanel left = Labels.flow();
		left.add(Labels.small("#" + rank, UIConstants.TEXT_MUTED));
		left.add(Labels.bold(Labels.ellipsize(team.getName(), FontManager.getRunescapeBoldFont(), mine ? NAME_WIDTH - 28 : NAME_WIDTH), UIConstants.TEXT_PRIMARY));
		if (mine) left.add(new Badge("YOU", color));
		top.add(left, BorderLayout.WEST);
		top.add(Labels.bold(team.getScore() + " pts", UIConstants.ACCENT_GOLD), BorderLayout.EAST);
		card.add(top);

		card.add(Box.createVerticalStrut(4));
		int regions = team.getUnlockedRegions().size();
		int doubled = 0;
		for (UnlockedRegion u : team.getUnlockedRegions()) {
			if (u.getBoardCompletedAt() != null) doubled++;
		}
		card.add(Labels.small(team.getUniqueCompletedTiles() + " tiles  |  " + regions + " region" + (regions != 1 ? "s" : "")
			+ (doubled > 0 ? "  |  " + doubled + " x2" : ""), UIConstants.TEXT_SECONDARY));

		Clickable.onPress(card, onOpen, card::setHovered);
		return card;
	}

	/** Colour dot, name and score; with tiles, regions and open picks when detailed. */
	static JComponent chip(Team team, Payload payload, boolean detailed) {
		Color color = LeaguesBingoPanel.teamColor(team);
		AccentCard card = new AccentCard(color, false);

		JPanel top = Labels.row();
		JPanel left = new JPanel(new FlowLayout(FlowLayout.LEFT, 6, 0));
		left.setOpaque(false);
		left.add(new ColorDot(color, 10));
		left.add(Labels.bold(Labels.ellipsize(team.getName(), FontManager.getRunescapeBoldFont(), NAME_WIDTH), UIConstants.TEXT_PRIMARY));
		top.add(left, BorderLayout.WEST);
		top.add(Labels.bold(team.getScore() + " pts", UIConstants.ACCENT_GOLD), BorderLayout.EAST);
		card.add(top);

		if (detailed) {
			card.add(Box.createVerticalStrut(4));
			int tokens = team.availableTokens();
			card.add(Labels.small(team.getUniqueCompletedTiles() + " tiles  |  " + team.getUnlockedRegions().size() + "/" + payload.getBoards().size() + " regions"
				+ (tokens > 0 ? "  |  " + tokens + " pick" + (tokens != 1 ? "s" : "") + " open" : ""), UIConstants.TEXT_SECONDARY));
		}
		return card;
	}
}

package com.revalclan.ui.leaguesbingo;

import com.revalclan.api.leaguesbingo.LeaguesBingoResponse.Tile;
import com.revalclan.ui.components.CheckIcon;
import com.revalclan.ui.constants.UIConstants;
import com.revalclan.util.Colors;
import net.runelite.client.ui.FontManager;

import javax.swing.JComponent;
import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.RenderingHints;
import java.awt.geom.RoundRectangle2D;

/**
 * One square of a Leagues Bingo board. Paints the same states the homepage
 * uses: completed (green), in progress (amber bar), untouched, filler for an
 * empty position, and a lock while tiles are still hidden.
 */
public class TileCell extends JComponent {
	public enum State { COMPLETED, IN_PROGRESS, NOT_STARTED, FILLER, HIDDEN }

	/** The shared success green (76, 175, 80); not themed. */
	public static final Color COMPLETED = UIConstants.SUCCESS_COLOR;
	public static final Color IN_PROGRESS = new Color(245, 158, 11);

	private final Tile tile;
	private final State state;
	private final int percent;
	private final Color accent;
	private final int size;

	private Image icon;
	private boolean hovered;
	private boolean selected;
	private boolean dimmed;

	public TileCell(Tile tile, State state, int percent, Color accent, int size) {
		this.tile = tile;
		this.state = state;
		this.percent = percent;
		this.accent = accent;
		this.size = size;
		Dimension d = new Dimension(size, size);
		setPreferredSize(d);
		setMinimumSize(d);
		setMaximumSize(d);
		setOpaque(false);
		if (tile != null) {
			setToolTipText(tile.getTask());
		}
	}

	public Tile getTile() {
		return tile;
	}

	public void setIcon(Image icon) {
		this.icon = icon;
		repaint();
	}

	public void setHovered(boolean hovered) {
		this.hovered = hovered;
		repaint();
	}

	public void setSelected(boolean selected) {
		this.selected = selected;
		repaint();
	}

	public void setDimmed(boolean dimmed) {
		this.dimmed = dimmed;
		repaint();
	}

	@Override
	protected void paintComponent(Graphics g) {
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		if (dimmed) {
			g2.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 0.45f));
		}

		int w = getWidth();
		int h = getHeight();
		int arc = Math.max(6, size / 6);
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, arc, arc);

		Color fill;
		Color border;
		switch (state) {
			case COMPLETED:
				fill = Colors.withAlpha(COMPLETED, hovered ? 70 : 45);
				border = Colors.withAlpha(COMPLETED, 150);
				break;
			case IN_PROGRESS:
				fill = Colors.withAlpha(IN_PROGRESS, hovered ? 55 : 30);
				border = Colors.withAlpha(IN_PROGRESS, 130);
				break;
			case FILLER:
				fill = UIConstants.ROW_BG;
				border = Colors.withAlpha(UIConstants.BORDER_COLOR, 90);
				break;
			case HIDDEN:
				fill = UIConstants.ROW_BG;
				border = UIConstants.BORDER_COLOR;
				break;
			default:
				fill = hovered ? UIConstants.CARD_HOVER : UIConstants.CARD_BG;
				border = UIConstants.BORDER_COLOR;
		}

		g2.setColor(fill);
		g2.fill(shape);

		if (state == State.FILLER) {
			paintWeave(g2, w, h, arc);
		} else if (state == State.HIDDEN) {
			paintLock(g2, w, h);
		} else if (icon != null) {
			paintIcon(g2, w, h);
		} else if (tile != null) {
			paintPosition(g2, w, h);
		}

		if (state == State.IN_PROGRESS) {
			int barH = Math.max(3, size / 14);
			int barW = (int) Math.round((w - 6) * Math.max(percent, BoardStats.MIN_VISIBLE_PERCENT) / 100d);
			g2.setColor(Colors.withAlpha(IN_PROGRESS, 60));
			g2.fillRoundRect(3, h - barH - 3, w - 6, barH, barH, barH);
			g2.setColor(IN_PROGRESS);
			g2.fillRoundRect(3, h - barH - 3, barW, barH, barH, barH);
		}

		g2.setStroke(new BasicStroke(selected ? 2f : 1f));
		g2.setColor(selected ? accent : border);
		g2.draw(shape);

		if (state == State.COMPLETED) {
			paintCheckBadge(g2, w);
		}

		g2.dispose();
	}

	private void paintIcon(Graphics2D g2, int w, int h) {
		int box = (int) Math.round(Math.min(w, h) * 0.72);
		// Item sprites from the game cache are 36x32 pixel art: keep them 1:1
		// whenever they fit, and only shrink them on tiny boards.
		int srcW = Math.max(1, icon.getWidth(null));
		int srcH = Math.max(1, icon.getHeight(null));
		double scale = Math.min(1d, Math.min((double) box / srcW, (double) box / srcH));
		int iw = Math.max(1, (int) Math.round(srcW * scale));
		int ih = Math.max(1, (int) Math.round(srcH * scale));
		int x = (w - iw) / 2;
		int y = (h - ih) / 2 - (state == State.IN_PROGRESS ? 2 : 0);
		g2.drawImage(icon, x, y, iw, ih, null);
	}

	private void paintPosition(Graphics2D g2, int w, int h) {
		g2.setFont(FontManager.getRunescapeSmallFont());
		g2.setColor(UIConstants.TEXT_MUTED);
		FontMetrics fm = g2.getFontMetrics();
		String text = tile.getPosition() != null ? tile.getPosition() : "";
		g2.drawString(text, (w - fm.stringWidth(text)) / 2, (h + fm.getAscent() - fm.getDescent()) / 2);
	}

	private void paintWeave(Graphics2D g2, int w, int h, int arc) {
		g2.setClip(new RoundRectangle2D.Float(1, 1, w - 2, h - 2, arc, arc));
		g2.setColor(Colors.withAlpha(accent, 22));
		g2.setStroke(new BasicStroke(1f));
		for (int i = -h; i < w + h; i += 6) {
			g2.drawLine(i, h, i + h, 0);
		}
		g2.setClip(null);
	}

	private void paintLock(Graphics2D g2, int w, int h) {
		int bw = Math.max(8, size / 4);
		int bh = Math.max(6, size / 5);
		int x = (w - bw) / 2;
		int y = (h - bh) / 2 + bh / 4;
		g2.setColor(UIConstants.TEXT_MUTED);
		g2.fillRoundRect(x, y, bw, bh, 3, 3);
		g2.setStroke(new BasicStroke(2f));
		int r = bw / 2 - 1;
		g2.drawArc(x + 1, y - r, bw - 2, r * 2, 0, 180);
	}

	/** Green disc in the top-right corner carrying the shared check mark. */
	private void paintCheckBadge(Graphics2D g2, int w) {
		int d = Math.max(10, size / 4);
		int x = w - d - 2;
		int y = 2;
		g2.setComposite(AlphaComposite.SrcOver);
		g2.setColor(COMPLETED);
		g2.fillOval(x, y, d, d);
		int inset = Math.max(2, d / 5);
		new CheckIcon(d - inset * 2, Color.WHITE).paintIcon(this, g2, x + inset, y + inset);
	}
}

package com.revalclan.ui.leaguesbingo;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.revalclan.api.leaguesbingo.LeaguesBingoResponse.Completion;
import com.revalclan.api.leaguesbingo.LeaguesBingoResponse.RequirementProgress;
import com.revalclan.api.leaguesbingo.LeaguesBingoResponse.Requirements;
import com.revalclan.api.leaguesbingo.LeaguesBingoResponse.Team;
import com.revalclan.api.leaguesbingo.LeaguesBingoResponse.Tile;
import com.revalclan.api.leaguesbingo.LeaguesBingoResponse.TileProgress;
import com.revalclan.ui.components.AccentCard;
import com.revalclan.ui.components.Badge;
import com.revalclan.ui.components.DotIcon;
import com.revalclan.ui.components.Labels;
import com.revalclan.ui.components.ProgressBar;
import com.revalclan.ui.constants.UIConstants;
import com.revalclan.util.DateTimeUtil;
import com.revalclan.util.Json;
import com.revalclan.util.NumberFmt;
import com.revalclan.util.TextWrap;
import net.runelite.client.ui.FontManager;

import javax.swing.Box;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

/** The card under the grid: one tile's task, status, requirements and who contributed. */
final class TileDetailView {
	private static final int TEXT_WIDTH = 158;
	private static final int DOT_SIZE = 9;
	private static final int DOT_GAP = 6;
	private static final int REQ_INDENT = DOT_SIZE + DOT_GAP;
	private static final int MAX_OPTIONS = 8;
	private static final int MAX_CONTRIBUTORS = 3;

	private TileDetailView() {
	}

	static JComponent build(Team team, Tile tile, boolean locked) {
		int percent = BoardStats.tilePercent(team, tile);
		boolean completed = percent >= 100;
		Color status = locked ? UIConstants.TEXT_MUTED : completed ? TileCell.COMPLETED : percent > 0 ? TileCell.IN_PROGRESS : UIConstants.TEXT_MUTED;
		AccentCard card = new AccentCard(status, false);

		JPanel top = Labels.row();
		top.add(Labels.small(tile.getPosition(), UIConstants.TEXT_MUTED), BorderLayout.WEST);
		top.add(Labels.bold(tile.getPoints() + " pt" + (tile.getPoints() != 1 ? "s" : ""), UIConstants.ACCENT_GOLD), BorderLayout.EAST);
		card.add(top);
		card.add(Box.createVerticalStrut(4));
		card.add(Labels.wrapped(tile.getTask(), FontManager.getRunescapeBoldFont(), UIConstants.TEXT_PRIMARY, TEXT_WIDTH));

		card.add(Box.createVerticalStrut(6));
		JPanel meta = Labels.flow();
		meta.setAlignmentX(Component.LEFT_ALIGNMENT);
		if (tile.getDifficulty() != null) meta.add(Badge.difficulty(tile.getDifficulty()));
		if (tile.getCategory() != null) meta.add(Badge.category(tile.getCategory()));
		card.add(meta);

		card.add(Box.createVerticalStrut(8));
		card.add(Labels.small(statusText(team, tile, locked, completed, percent), status));
		if (!locked && (completed || percent > 0)) {
			card.add(Box.createVerticalStrut(5));
			card.add(new ProgressBar(percent, status));
		}

		Requirements reqs = tile.getRequirements();
		List<JsonObject> list = reqs != null ? reqs.getRequirements() : new ArrayList<>();
		if (!list.isEmpty()) {
			card.add(Box.createVerticalStrut(10));
			String match = list.size() > 1 ? (reqs.isAnyMatch() ? "  (any)" : "  (all)") : "";
			card.add(Labels.small("Requirements" + match, UIConstants.TEXT_SECONDARY));
			TileProgress progress = team.progressFor(tile.getBoardTileId());
			for (int i = 0; i < list.size(); i++) {
				RequirementProgress rp = progress != null ? progress.requirement(i) : null;
				// 'any' tiles finish on one requirement, so only rows the
				// progress data flags count as done; 'all' tiles finish only
				// when every row is done.
				boolean rowDone = rp != null && rp.isCompleted() || (completed && !reqs.isAnyMatch());
				card.add(Box.createVerticalStrut(5));
				card.add(requirementRow(list.get(i), rp, rowDone));
			}
		}

		if (tile.getDescription() != null && !tile.getDescription().trim().isEmpty()) {
			card.add(Box.createVerticalStrut(8));
			card.add(Labels.wrapped(tile.getDescription(), FontManager.getRunescapeSmallFont(), UIConstants.TEXT_MUTED, TEXT_WIDTH));
		}
		return card;
	}

	private static String statusText(Team team, Tile tile, boolean locked, boolean completed, int percent) {
		if (locked) return "Locked for this team";
		if (completed) {
			Completion done = team.completionFor(tile.getBoardTileId());
			return "Completed" + (done != null && done.getCompletedAt() != null ? "  |  " + DateTimeUtil.formatShort(done.getCompletedAt()) : "");
		}
		return percent > 0 ? "In progress  |  " + percent + "%" : "Not started";
	}

	/**
	 * Dot + description on the first line (the count at its end), wrapped
	 * continuation lines, the option list with obtained names in green, and
	 * the contributors, all hanging under the text.
	 */
	private static JComponent requirementRow(JsonObject requirement, RequirementProgress rp, boolean done) {
		JPanel text = Labels.column();
		text.setAlignmentX(Component.LEFT_ALIGNMENT);

		Font font = FontManager.getRunescapeSmallFont();
		Color color = done ? TileCell.COMPLETED : UIConstants.TEXT_SECONDARY;
		FontMetrics fm = new JLabel().getFontMetrics(font);

		String count = progressCount(rp);
		int countWidth = count != null ? fm.stringWidth(count) + 8 : 0;

		// A plain label carries the dot as its icon, so Swing centers the two
		// on one line; HTML wrapping would put the dot at the block's top.
		List<String> lines = TextWrap.wrap(RequirementText.describe(requirement), fm, TEXT_WIDTH - REQ_INDENT - countWidth);
		JLabel first = new JLabel(lines.isEmpty() ? "" : lines.get(0),
			new DotIcon(done, DOT_SIZE, TileCell.COMPLETED, UIConstants.TEXT_MUTED), JLabel.LEFT);
		first.setFont(font);
		first.setForeground(color);
		first.setIconTextGap(DOT_GAP);

		JPanel firstLine = new JPanel(new BorderLayout(8, 0));
		firstLine.setOpaque(false);
		firstLine.setAlignmentX(Component.LEFT_ALIGNMENT);
		firstLine.add(first, BorderLayout.CENTER);
		if (count != null) {
			firstLine.add(Labels.label(count, font, done ? TileCell.COMPLETED : TileCell.IN_PROGRESS), BorderLayout.EAST);
		}
		firstLine.setMaximumSize(new Dimension(Integer.MAX_VALUE, firstLine.getPreferredSize().height));
		text.add(firstLine);
		for (int i = 1; i < lines.size(); i++) {
			text.add(indented(Labels.label(lines.get(i), font, color)));
		}

		List<String> options = RequirementText.optionNames(requirement);
		if (options.size() > 1) {
			text.add(indented(optionsLabel(options, obtainedNames(rp != null ? rp.getProgressMetadata() : null), font)));
		}

		String who = rp != null ? contributors(rp.getProgressMetadata()) : "";
		if (!who.isEmpty()) {
			text.add(indented(Labels.wrapped("by " + who, font, done ? TileCell.COMPLETED : TileCell.IN_PROGRESS, TEXT_WIDTH - REQ_INDENT)));
		}
		return text;
	}

	private static JLabel indented(JLabel label) {
		label.setBorder(new EmptyBorder(0, REQ_INDENT, 0, 0));
		return label;
	}

	/** Obtained names first (green) so they survive the cap on long lists (49 pets...). */
	private static JLabel optionsLabel(List<String> options, Set<String> obtained, Font font) {
		List<String> ordered = new ArrayList<>();
		for (String n : options) if (obtained.contains(n.toLowerCase())) ordered.add(n);
		for (String n : options) if (!obtained.contains(n.toLowerCase())) ordered.add(n);
		StringBuilder html = new StringBuilder();
		int shown = Math.min(ordered.size(), MAX_OPTIONS);
		for (int i = 0; i < shown; i++) {
			if (i > 0) html.append(", ");
			String name = ordered.get(i);
			String escaped = Labels.escapeHtml(name);
			html.append(obtained.contains(name.toLowerCase()) ? "<span style='color:#4caf50'>" + escaped + "</span>" : escaped);
		}
		if (ordered.size() > shown) html.append(" +").append(ordered.size() - shown).append(" more");
		return Labels.wrappedHtml(html.toString(), font, UIConstants.TEXT_MUTED, TEXT_WIDTH - REQ_INDENT);
	}

	/** "current/target" when the requirement counts past one, else null. */
	private static String progressCount(RequirementProgress rp) {
		if (rp == null) return null;
		JsonObject meta = rp.getProgressMetadata();
		Double target = Json.number(meta, "targetValue");
		Double current = Json.number(meta, "currentTotalCount");
		if (current == null) current = rp.getProgressValue();
		if (target == null || target <= 1 || current == null) return null;
		return NumberFmt.group(Math.round(current)) + "/" + NumberFmt.group(Math.round(target));
	}

	/** Item and pet names (lowercased) the team has already turned in for this requirement. */
	private static Set<String> obtainedNames(JsonObject meta) {
		Set<String> names = new HashSet<>();
		if (meta == null) return names;
		collectNames(Json.array(meta, "lastItemsObtained"), names);
		JsonArray contributions = Json.array(meta, "playerContributions");
		if (contributions != null) {
			for (JsonElement c : contributions) {
				if (!c.isJsonObject()) continue;
				collectNames(Json.array(c.getAsJsonObject(), "items"), names);
				collectNames(Json.array(c.getAsJsonObject(), "pets"), names);
			}
		}
		return names;
	}

	private static void collectNames(JsonArray array, Set<String> into) {
		for (String n : Json.strings(array, "itemName")) into.add(n.toLowerCase());
		for (String n : Json.strings(array, "petName")) into.add(n.toLowerCase());
	}

	private static String contributors(JsonObject meta) {
		// Each nickname once, in order of first contribution.
		List<String> names = new ArrayList<>(new LinkedHashSet<>(Json.strings(Json.array(meta, "playerContributions"), "osrsNickname")));
		if (names.size() > MAX_CONTRIBUTORS) {
			return String.join(", ", names.subList(0, MAX_CONTRIBUTORS)) + " +" + (names.size() - MAX_CONTRIBUTORS);
		}
		return String.join(", ", names);
	}
}

package com.revalclan.ui.leaguesbingo;

import com.revalclan.api.leaguesbingo.LeaguesBingoResponse.Tile;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.http.api.item.ItemPrice;

import javax.swing.SwingUtilities;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Tile icons from the game's item cache, never the wiki. The backend sends
 * the item id it resolved for the tile's icon; the one fallback is an exact
 * name match against the price list, for tiles it could not resolve.
 */
public class TileIcons {
	private final ItemManager itemManager;
	/** Icon name -> item id from the fallback search; null marks a miss. */
	private final Map<String, Integer> searched = new HashMap<>();

	public TileIcons(ItemManager itemManager) {
		this.itemManager = itemManager;
	}

	public void load(Tile tile, TileCell cell) {
		if (itemManager == null) return;
		Integer itemId = tile.getIconItemId() != null ? tile.getIconItemId() : searchByName(tile.getIcon());
		if (itemId == null) return;
		try {
			AsyncBufferedImage image = itemManager.getImage(itemId);
			cell.setIcon(image);
			image.onLoaded(() -> SwingUtilities.invokeLater(cell::repaint));
		} catch (RuntimeException ignored) {
			// A bad id must never break the grid.
		}
	}

	private Integer searchByName(String iconName) {
		if (iconName == null || iconName.trim().isEmpty()) return null;
		String name = iconName.trim().replace('_', ' ');
		if (searched.containsKey(name)) return searched.get(name);
		Integer found = null;
		try {
			List<ItemPrice> results = itemManager.search(name);
			for (ItemPrice p : results) {
				if (p.getName() != null && p.getName().equalsIgnoreCase(name)) {
					found = p.getId();
					break;
				}
			}
		} catch (RuntimeException ignored) {
			// Price list unavailable: leave the tile without an icon.
		}
		searched.put(name, found);
		return found;
	}
}

package com.revalclan.util;

import com.revalclan.api.RevalApiService;
import com.revalclan.api.announcements.AnnouncementsResponse.Announcement;
import com.revalclan.api.notifications.NotificationsResponse.Notification;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.*;
import java.util.concurrent.CopyOnWriteArrayList;

@Singleton
public class AnnouncementService {
	private static final int NOTIFICATION_INTERVAL_TICKS = 6000; // ~60 minutes; login and heartbeat hints fetch sooner.
	private int notificationTicksRemaining = NOTIFICATION_INTERVAL_TICKS;
	private static final int INITIAL_DELAY_TICKS = 5;
	private static final int RETRY_TICKS = 100; // ~1 minute.

	@Inject private ChatMessageManager chatMessageManager;
	@Inject private RevalApiService revalApiService;
	@Inject private Client client;
	@Inject private com.revalclan.RevalClanConfig config;

	private int sessionGeneration;
	private String appliedNotificationVersion;
	private int tickCounter = 0;
	private boolean initialFetchDone = false;
	private boolean announcementFetchInProgress = false;
	private boolean notificationFetchInProgress = false;

	private final Set<Integer> shownBroadcastIds = new HashSet<>();
	private final Map<Integer, Long> lastChatShownTime = new HashMap<>();
	private final List<Announcement> cachedAnnouncements = new CopyOnWriteArrayList<>();

	public synchronized void onGameTick() {
		if (!config.showAnnouncements()) {
			return;
		}

		tickCounter++;

		if (tickCounter < INITIAL_DELAY_TICKS) {
			return;
		}

		if (!initialFetchDone) {
			initialFetchDone = true;
			fetchAnnouncements();
			fetchNotifications();
			return;
		}

		if (!notificationFetchInProgress && --notificationTicksRemaining <= 0) {
			fetchNotifications();
		}

		processChatAnnouncements();
	}

	/** Called on the client thread after a current login/heartbeat response. */
	public synchronized void onServerVersion(String version) {
		if (config.showAnnouncements() && initialFetchDone
			&& (version == null || !version.equals(appliedNotificationVersion))) fetchNotifications();
	}

	private void fetchAnnouncements() {
		if (announcementFetchInProgress) {
			return;
		}
		announcementFetchInProgress = true;
		final int generation = sessionGeneration;

		revalApiService.fetchAnnouncements(
			response -> {
				synchronized (AnnouncementService.this) {
					if (generation != sessionGeneration) return;
					announcementFetchInProgress = false;
					if (response.getData() != null && response.getData().getAnnouncements() != null) {
						cachedAnnouncements.clear();
						cachedAnnouncements.addAll(response.getData().getAnnouncements());
						processBroadcasts();
					}
				}
			},
			error -> {
				synchronized (AnnouncementService.this) {
					if (generation != sessionGeneration) return;
					announcementFetchInProgress = false;
				}
			}
		);
	}

	private void fetchNotifications() {
		if (notificationFetchInProgress) {
			return;
		}

		long accountHash = client.getAccountHash();
		if (accountHash == -1) {
			return;
		}

		notificationFetchInProgress = true;
		notificationTicksRemaining = NOTIFICATION_INTERVAL_TICKS;
		final int generation = sessionGeneration;
		revalApiService.fetchNotifications(accountHash,
			response -> {
				synchronized (AnnouncementService.this) {
					if (generation != sessionGeneration) return;
					notificationFetchInProgress = false;
					if (response.getData() != null && response.getData().getNotifications() != null) {
						appliedNotificationVersion = response.getData().getVersion();
					} else {
						notificationTicksRemaining = RETRY_TICKS;
					}
					if (response.getData() != null && response.getData().getNotifications() != null
						&& !response.getData().getNotifications().isEmpty()) {
						displayAndAcknowledgeNotifications(accountHash, response.getData().getNotifications());
					}
				}
			},
			error -> {
				synchronized (AnnouncementService.this) {
					if (generation != sessionGeneration) return;
					notificationFetchInProgress = false;
					notificationTicksRemaining = RETRY_TICKS;
				}
			}
		);
	}

	private void processBroadcasts() {
		cachedAnnouncements.stream()
			.filter(Announcement::isBroadcast)
			.filter(a -> !shownBroadcastIds.contains(a.getId()))
			.sorted(Comparator.comparingInt(Announcement::getPriority).reversed())
			.forEach(a -> {
				chatMessageManager.queue(QueuedMessage.builder()
					.type(ChatMessageType.BROADCAST)
					.runeLiteFormattedMessage(formatMessage(a.getTitle(), a.getMessage()))
					.build());
				shownBroadcastIds.add(a.getId());
			});
	}

	private void processChatAnnouncements() {
		long now = System.currentTimeMillis();

		for (Announcement a : cachedAnnouncements) {
			if (!a.isChat()) {
				continue;
			}

			long intervalMs = a.getIntervalMinutes() * 60L * 1000L;
			Long lastShown = lastChatShownTime.get(a.getId());

			if (lastShown != null && (now - lastShown) < intervalMs) {
				continue;
			}

			chatMessageManager.queue(QueuedMessage.builder()
				.type(ChatMessageType.CLAN_MESSAGE)
				.sender("Reval")
				.runeLiteFormattedMessage("<col=FFD700>" + a.getMessage() + "</col>")
				.build());
			lastChatShownTime.put(a.getId(), now);
		}
	}

	private void displayAndAcknowledgeNotifications(long accountHash, List<Notification> notifications) {
		List<Integer> idsToAck = new ArrayList<>();

		for (Notification notification : notifications) {
			chatMessageManager.queue(QueuedMessage.builder()
				.type(ChatMessageType.BROADCAST)
				.runeLiteFormattedMessage(formatNotificationMessage(notification))
				.build());
			idsToAck.add(notification.getId());
		}

		if (!idsToAck.isEmpty()) {
			revalApiService.acknowledgeNotifications(accountHash, idsToAck,
				ackResponse -> {},
				error -> {}
			);
		}
	}

	private String formatNotificationMessage(Notification notification) {
		return formatMessage(notification.getTitle(), notification.getMessage());
	}

	/** Broadcasts and notifications share one look: gold "[Reval] Title:" (or "[Reval]") then the message. */
	private static String formatMessage(String title, String message) {
		if (title != null && !title.isEmpty()) {
			return "<col=FFD700>[Reval] " + title + ":</col> " + message;
		}
		return "<col=FFD700>[Reval]</col> " + message;
	}

	public synchronized void reset() {
		sessionGeneration++;
		appliedNotificationVersion = null;
		notificationTicksRemaining = NOTIFICATION_INTERVAL_TICKS;
		tickCounter = 0;
		initialFetchDone = false;
		announcementFetchInProgress = false;
		notificationFetchInProgress = false;
		shownBroadcastIds.clear();
		lastChatShownTime.clear();
		cachedAnnouncements.clear();
	}
}

package com.revalclan.util;

import java.util.EnumSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.events.ScriptCallbackEvent;
import net.runelite.client.util.Text;

/**
 * The Fractured Archive broadcasts every regular reward to friends and clan chats
 * as "(very valuable)" (a known Jagex bug). Those lines are dropped before chat
 * renders them, the same way RuneLite's Chat Filter blocks a message; the raid's
 * rare rewards and Cabbage stay visible. Other raids' broadcasts lack the suffix.
 */
public final class ArchiveLootBroadcasts {
	private static final Set<ChatMessageType> BROADCASTS = EnumSet.of(ChatMessageType.CLAN_MESSAGE,
		ChatMessageType.CLAN_GUEST_MESSAGE, ChatMessageType.CLAN_GIM_MESSAGE, ChatMessageType.FRIENDSCHATNOTIFICATION);

	private static final Pattern VERY_VALUABLE_RAID_LOOT = Pattern.compile(
		"received special loot from a raid: (?:[\\d,]+ x )?(.+) \\(very valuable\\)\\.?$", Pattern.CASE_INSENSITIVE);

	/** Name prefixes of the uniques, pet, collection log tertiaries and the poor-run Cabbage. */
	private static final List<String> KEPT = List.of("rondache", "zorya's tome", "horn of bran",
		"ascension crossbows", "obligator", "orion", "fragment of ", "archivist's folio", "cabbage");

	private ArchiveLootBroadcasts() {}

	/** Blocks the message being checked; the stack layout matches RuneLite's ChatFilterPlugin. */
	public static void filter(Client client, ScriptCallbackEvent event) {
		if (!"chatFilterCheck".equals(event.getEventName())) return;
		int[] ints = client.getIntStack();
		int size = client.getIntStackSize();
		Object message = client.getObjectStack()[client.getObjectStackSize() - 1];
		if (message instanceof String && hidden(ChatMessageType.of(ints[size - 2]), (String) message)) {
			ints[size - 3] = 0;
		}
	}

	static boolean hidden(ChatMessageType type, String message) {
		if (!BROADCASTS.contains(type)) return false;
		Matcher loot = VERY_VALUABLE_RAID_LOOT.matcher(Text.removeTags(message).replace(' ', ' ').trim());
		if (!loot.find()) return false;
		String item = loot.group(1).toLowerCase(Locale.ROOT);
		return KEPT.stream().noneMatch(item::startsWith);
	}
}

package com.revalclan.util;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.client.util.Text;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;
import java.util.regex.Pattern;

/** Native Archive roster evidence for one observed run, retained briefly for its rewards. */
@Singleton
final class ArchiveRoster {
	private static final int MAX_PARTY_SIZE = 8;
	private static final Set<Integer> IN_RAID_PARTY_STATES = Set.of(2, 3);
	private static final long RETENTION_MS = 10 * 60_000L;
	private static final Pattern PLAYER_NAME = Pattern.compile("[a-zA-Z0-9 _-]{1,12}");

	@Inject private Client client;
	private final Map<String, String> names = new LinkedHashMap<>();
	private int maxSize;
	private int verifiedSize;
	private int completionCount = -1;
	private boolean inside;
	private boolean completed;
	private RaidPartyTracker.Party completedParty;
	private long lastActiveAt;

	/** Capture native names and occupied slots; no clan lookup or Party allocation on ticks. */
	void observe() {
		if (client.getGameState() != GameState.LOGGED_IN) return;
		WorldView world = client.getTopLevelWorldView();
		boolean active = IN_RAID_PARTY_STATES.contains(client.getVarbitValue(VarbitID.TFA_CLIENT_PARTYSTATUS))
			&& world != null && world.isInstance();
		long now = System.currentTimeMillis();
		if (active && !inside) clearRun();
		inside = active;
		if (!inside) {
			if (now - lastActiveAt > RETENTION_MS) clearRun();
			return;
		}
		if (completed) return;

		int size = 0;
		Set<String> liveNames = new HashSet<>();
		Set<String> occupiedNames = new HashSet<>();
		for (int i = 0; i < MAX_PARTY_SIZE; i++) {
			boolean occupied = client.getVarbitValue(VarbitID.TFA_CLIENT_P0 + i) > 0;
			if (occupied) size++;
			String raw = client.getVarcStrValue(VarClientID.TFA_CLIENT_NAME0 + i);
			String name = raw == null ? "" : Text.removeTags(raw).replace('\u00a0', ' ').trim();
			String key = RaidPartyTracker.nameKey(name);
			if (!PLAYER_NAME.matcher(name).matches() || key.trim().isEmpty()) continue;
			liveNames.add(key);
			if (occupied) occupiedNames.add(key);
			names.putIfAbsent(key, name);
		}
		maxSize = Math.max(maxSize, size);
		// Stale names in empty slots cannot fill an unknown occupied slot.
		if (size > 0 && occupiedNames.size() == size && occupiedNames.equals(liveNames)) {
			verifiedSize = Math.max(verifiedSize, size);
		}
		lastActiveAt = now;
	}

	RaidPartyTracker.Party complete(int count) {
		observe();
		if (count <= completionCount) return null;
		completionCount = count;
		// A second completion without an observed new entry has unknown participants.
		if (completed) names.clear();
		completed = true;
		if (!names.isEmpty()) lastActiveAt = System.currentTimeMillis();
		// Keep the final tick's death snapshot with the names until this reward expires.
		completedParty = names.isEmpty() ? null : RaidPartyTracker.Party.of(RaidPartyTracker.FRACTURED_ARCHIVE,
			RaidPartyTracker.Origin.COMPLETION, new ArrayList<>(names.values()), null);
		return completedParty;
	}

	RaidPartyTracker.Party party(Set<String> revalRoster) {
		observe();
		if (names.isEmpty()) return null;
		Player local = client.getLocalPlayer();
		boolean complete = maxSize > 0 && verifiedSize == maxSize && names.size() == maxSize
			&& local != null && names.containsKey(RaidPartyTracker.nameKey(local.getName()));
		RaidPartyTracker.Party party = completedParty != null ? completedParty.withClanRoster(revalRoster)
			: RaidPartyTracker.Party.of(RaidPartyTracker.FRACTURED_ARCHIVE,
				RaidPartyTracker.Origin.LIVE, new ArrayList<>(names.values()), revalRoster);
		return party.withRosterEvidence(maxSize, complete);
	}

	void reset() {
		clearRun();
		inside = false;
		completionCount = -1;
	}

	private void clearRun() {
		names.clear();
		maxSize = 0;
		verifiedSize = 0;
		completed = false;
		completedParty = null;
		lastActiveAt = 0;
	}
}

package com.revalclan.util;

import com.revalclan.util.ClanValidator.Probe;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;

import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Cached "is this player a Reval member" answer for the current login.
 *
 * Proven once per login from the clan settings (or the channel, whichever
 * loads first) and then kept for the rest of the login: the channel drops for
 * a few ticks on every hop, and a player who left the chat channel has a null
 * channel for the rest of their login while still being a member — the case
 * that used to silence the plugin entirely. The state resets on the login
 * screen so every login re-proves it (an alt that is not in Reval is simply
 * never proven).
 *
 * The backend is the final authority (it knows the roster from Wise Old Man);
 * this gate only decides what the client bothers to send.
 */
@Slf4j
@Singleton
public class ClanMembership {
	@Inject private Client client;

	private volatile boolean member = false;

	/** Current answer. Safe from any thread. */
	public boolean isMember() {
		return member;
	}

	/**
	 * Probe the sources until membership is proven (client thread, every
	 * tick; a no-op once proven). Returns true exactly on the tick the answer
	 * flips to member, so the caller can run its once-per-login hooks.
	 */
	public boolean refresh() {
		if (member || client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null) return false;
		String name = client.getLocalPlayer().getName();
		if (name == null) return false;

		Probe settings = ClanValidator.probeSettings(client, name);
		if (settings != Probe.MEMBER && ClanValidator.probeChannel(client, name) != Probe.MEMBER) return false;
		member = true;
		log.info("Clan membership proven (settings={})", settings);
		return true;
	}

	/** New login must re-prove membership. */
	public void reset() {
		member = false;
	}
}

package com.revalclan.util;

import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.SpriteManager;

import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.JLabel;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import java.util.function.IntConsumer;

/**
 * Resolves clan rank titles (e.g. "Red Topaz") to their in-game clan icon
 * sprite ids using the game's own enums (CLAN_RANK_NAME → CLAN_RANK_GRAPHIC),
 * so icons stay correct for every rank without hardcoding sprite ids. Falls
 * back to a small verified static map when the cache lookup is unavailable.
 */
@Singleton
public class ClanRankIconResolver {
	private static final Map<String, Integer> FALLBACK_SPRITES = Map.ofEntries(
		Map.entry("mentor", 3137),
		Map.entry("prefect", 3138),
		Map.entry("leader", 3139),
		Map.entry("supervisor", 3140),
		Map.entry("superior", 3141),
		Map.entry("executive", 3142),
		Map.entry("senator", 3143),
		Map.entry("monarch", 3144),
		Map.entry("red_topaz", 3129),
		Map.entry("sapphire", 3130),
		Map.entry("emerald", 3131),
		Map.entry("ruby", 3132),
		Map.entry("diamond", 3133),
		Map.entry("dragonstone", 3134),
		Map.entry("onyx", 3135),
		Map.entry("zenyte", 3136),
		Map.entry("marshal", 3111)
	);

	private final Client client;
	private final ClientThread clientThread;
	private final SpriteManager spriteManager;
	private volatile Map<String, Integer> titleToSprite;

	@Inject
	public ClanRankIconResolver(Client client, ClientThread clientThread, SpriteManager spriteManager) {
		this.client = client;
		this.clientThread = clientThread;
		this.spriteManager = spriteManager;
	}

	/**
	 * Resolve a rank slug or title to a sprite id. The callback fires at most
	 * once, possibly on the client thread; it is skipped when no icon is known.
	 */
	public void resolve(String rankName, IntConsumer callback) {
		if (rankName == null) {
			return;
		}
		String title = RankNames.display(rankName).toLowerCase(Locale.ROOT);

		Map<String, Integer> cached = titleToSprite;
		if (cached != null) {
			deliver(cached, title, callback);
			return;
		}

		clientThread.invoke(() -> {
			Map<String, Integer> map = titleToSprite;
			if (map == null) {
				map = buildMap();
				if (!map.isEmpty()) {
					titleToSprite = map;
				}
			}
			deliver(map, title, callback);
		});
	}

	/**
	 * Resolve a rank's icon and set it on a Swing label, scaled to fit inside
	 * a size x size box with the sprite's aspect ratio preserved.
	 */
	public void apply(String rankName, JLabel target, int size) {
		if (target == null) {
			return;
		}
		resolve(rankName, spriteId -> SpriteIcons.apply(spriteManager, spriteId, target, size));
	}

	private void deliver(Map<String, Integer> map, String title, IntConsumer callback) {
		Integer spriteId = map.get(title);
		if (spriteId == null) {
			spriteId = FALLBACK_SPRITES.get(title.replace(' ', '_'));
		}
		if (spriteId != null) {
			callback.accept(spriteId);
		}
	}

	private Map<String, Integer> buildMap() {
		Map<String, Integer> map = new HashMap<>();
		try {
			EnumComposition names = client.getEnum(EnumID.CLAN_RANK_NAME);
			EnumComposition graphics = client.getEnum(EnumID.CLAN_RANK_GRAPHIC);
			for (int key : names.getKeys()) {
				String title = names.getStringValue(key);
				int sprite = graphics.getIntValue(key);
				if (title != null && !title.isEmpty() && sprite > 0) {
					map.put(title.toLowerCase(Locale.ROOT), sprite);
				}
			}
		} catch (Exception ignored) {
			// Cache not ready — callers get the static fallback instead
		}
		return map;
	}
}

package com.revalclan.util;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.clan.ClanChannel;
import net.runelite.api.clan.ClanChannelMember;

/** In-game clan rank checks shared by admin-gated UI. */
public final class ClanRanks {
	/** Deputy Owner and above - the rank the plugin treats as clan staff. */
	private static final int ADMIN_MIN_RANK = 125;

	private ClanRanks() {
	}

	public static boolean isDeputyOwnerPlus(Client client) {
		if (client.getGameState() != GameState.LOGGED_IN) {
			return false;
		}
		ClanChannel clanChannel = client.getClanChannel();
		String name = client.getLocalPlayer() != null ? client.getLocalPlayer().getName() : null;
		if (clanChannel == null || name == null) {
			return false;
		}
		ClanChannelMember member = clanChannel.findMember(name);
		return member != null && member.getRank().getRank() >= ADMIN_MIN_RANK;
	}
}

package com.revalclan.util;

import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

import java.util.function.Consumer;
import java.util.regex.Pattern;

/** Iteration over the clan sidepanel member list's name widgets. */
public final class ClanSidepanel {
	/** Rows hold a name widget and a world widget ("W123"); worlds are skipped. */
	private static final Pattern WORLD_TEXT = Pattern.compile("W\\d+");

	private ClanSidepanel() {
	}

	/** Calls {@code consumer} with each member-name text widget in the list. */
	public static void eachNameRow(Client client, Consumer<Widget> consumer) {
		Widget list = client.getWidget(InterfaceID.ClansSidepanel.PLAYERLIST);
		if (list == null) {
			return;
		}
		Widget[] children = list.getDynamicChildren();
		if (children == null) {
			return;
		}
		for (Widget child : children) {
			String text = child.getText();
			if (text == null || text.isEmpty() || WORLD_TEXT.matcher(text).matches()) {
				continue;
			}
			consumer.accept(child);
		}
	}
}

package com.revalclan.util;

import net.runelite.api.Client;
import net.runelite.api.clan.ClanChannel;
import net.runelite.api.clan.ClanChannelMember;
import net.runelite.api.clan.ClanMember;
import net.runelite.api.clan.ClanRank;
import net.runelite.api.clan.ClanSettings;

/**
 * Constants and stateless clan-membership probes. {@link ClanMembership}
 * owns the cached answer; these only read what the client currently knows.
 *
 * Two sources, verified in-client (2026-09-10):
 * <ul>
 *   <li><b>Clan settings</b> — the clan the account belongs to. Available 2–5
 *       ticks after login/hop, survives a LEFT clan channel, a relog and a
 *       client restart. The authoritative source.</li>
 *   <li><b>Clan channel</b> — the chat channel. Null for ~4 ticks after every
 *       hop, null indefinitely once the player leaves the channel, and can be
 *       a stale object from the previous session at LOGGING_IN. Only an
 *       accelerator.</li>
 * </ul>
 */
public final class ClanValidator {
	/** Required clan name (null or empty to disable clan check) */
	public static final String REQUIRED_CLAN_NAME = "Reval";

	/** Minimum clan rank required (-1 to 127, higher = more permissions). 0 = any member. */
	public static final int MINIMUM_CLAN_RANK = 0;

	private ClanValidator() {}

	/** Tri-state probe result: the source is not loaded, says member, or says not a member. */
	public enum Probe { UNKNOWN, MEMBER, NOT_MEMBER }

	public static boolean isCheckDisabled() {
		return REQUIRED_CLAN_NAME == null || REQUIRED_CLAN_NAME.trim().isEmpty();
	}

	/** What the clan settings say about {@code playerName}. */
	public static Probe probeSettings(Client client, String playerName) {
		if (isCheckDisabled()) return Probe.MEMBER;
		ClanSettings settings = client.getClanSettings();
		if (settings == null || playerName == null) return Probe.UNKNOWN;
		if (!REQUIRED_CLAN_NAME.equalsIgnoreCase(settings.getName())) return Probe.NOT_MEMBER;
		ClanMember member = settings.findMember(playerName);
		if (member == null) return Probe.NOT_MEMBER;
		return rankOk(member.getRank()) ? Probe.MEMBER : Probe.NOT_MEMBER;
	}

	/** What the clan channel says about {@code playerName}. */
	public static Probe probeChannel(Client client, String playerName) {
		if (isCheckDisabled()) return Probe.MEMBER;
		ClanChannel channel = client.getClanChannel();
		if (channel == null || playerName == null) return Probe.UNKNOWN;
		if (!REQUIRED_CLAN_NAME.equalsIgnoreCase(channel.getName())) return Probe.NOT_MEMBER;
		ClanChannelMember member = channel.findMember(playerName);
		if (member == null) return Probe.UNKNOWN; // channel roster is only who is online
		return rankOk(member.getRank()) ? Probe.MEMBER : Probe.NOT_MEMBER;
	}

	private static boolean rankOk(ClanRank rank) {
		return rank == null || rank.getRank() >= MINIMUM_CLAN_RANK;
	}
}

