package com.revalclan.util;

import java.time.Instant;
import java.time.LocalDateTime;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;

public class DateTimeUtil {
	private static final DateTimeFormatter SHORT = DateTimeFormatter.ofPattern("MMM d HH:mm");

	/** "Sep 4 21:59" in the user's zone; the raw string when it does not parse. */
	public static String formatShort(String iso) {
		try {
			return parseToLocal(iso).format(SHORT);
		} catch (RuntimeException e) {
			return iso;
		}
	}


	/**
	 * Parses an ISO 8601 timestamp (with or without zone) as UTC,
	 * then converts to the user's local timezone.
	 */
	public static ZonedDateTime parseToLocal(String iso) {
		try {
			return ZonedDateTime.parse(iso)
				.withZoneSameInstant(ZoneId.systemDefault());
		} catch (DateTimeParseException e) {
			return LocalDateTime.parse(iso)
				.atZone(ZoneOffset.UTC)
				.withZoneSameInstant(ZoneId.systemDefault());
		}
	}

	/**
	 * Parses an ISO 8601 timestamp (with or without zone) to a UTC Instant.
	 */
	public static Instant parseToInstant(String iso) {
		try {
			return Instant.parse(iso);
		} catch (DateTimeParseException e) {
			return LocalDateTime.parse(iso).toInstant(ZoneOffset.UTC);
		}
	}
}

package com.revalclan.util;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import lombok.Getter;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import okhttp3.*;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.IOException;
import java.util.*;
import java.util.List;
import java.util.function.Consumer;

/**
 * Manages dynamic event filters fetched from the backend API
 */
@Slf4j
@Singleton
public class EventFilterManager{
	private static final String FILTERS_URL = "https://api.revalosrs.ee/event-filters";

	@Inject private OkHttpClient httpClient;

	@Inject private Gson gson;

	@Getter private volatile EventFilters filters;
	private String appliedVersion;
	private boolean fetchInProgress;
	private int generation;
	private int ticksRemaining;
	private static final int DAILY_TICKS = 144_000;
	private static final int RETRY_TICKS = 100; // One minute after a failed fetch.

	/** Runs after every successful fetch, once the new filters are in place. */
	@Setter private Runnable onFiltersApplied;

	/**
	 * Holds all filter configurations
	 */
	@Getter
	public static class EventFilters {
		// Loot filter settings
		private long lootMinValue = 1_000_000; // 1M default
		private Set<Integer> lootWhitelist = new HashSet<>();
		private Set<Integer> lootBlacklist = new HashSet<>(Arrays.asList(526, 995)); // Bones, Coins

		// Detailed kill filter settings
		private Set<Integer> detailedKillNpcIdWhitelist = new HashSet<>();
		private Set<Integer> detailedKillNpcIdBlacklist = new HashSet<>();
		/** NPC names (lowercase) needed by active server-side requirements; matched by containment */
		private Set<String> detailedKillNpcNameWhitelist = new HashSet<>();

		// Chat filter settings
		private List<String> chatPatterns = new ArrayList<>(); // Empty by default = no patterns, all messages pass

		/**
		 * Item names (lowercase) whose silent consumption is reported. Derived by
		 * the backend from live tile requirements; nothing is built into the
		 * plugin, and empty means watch nothing.
		 */
		private Set<String> inventoryWatchItems = new HashSet<>();
		/** Watched item names as the backend spelled them, keyed lowercased. */
		private Map<String, String> inventoryWatchItemNames = new HashMap<>();

		/** Varbit ids whose value the plugin reports (varbits.watch). Empty by default. */
		private Set<Integer> varbitWatch = new HashSet<>();

		// Event toggles
		private boolean lootEnabled = true;
		private boolean petEnabled = true;
		private boolean questEnabled = true;
		private boolean levelEnabled = true;
		private boolean killCountEnabled = true;
		private boolean clueEnabled = true;
		private boolean diaryEnabled = true;
		private boolean combatAchievementEnabled = true;
		private boolean collectionEnabled = true;
		private boolean deathEnabled = true;
		private boolean detailedKillEnabled = true;
		private boolean emoteEnabled = true;
		private boolean chatEnabled = true;
		private boolean musicEnabled = true;
		private boolean leaguesEnabled = false;
	}

	public EventFilterManager() {
		// Initialize with defaults
		filters = new EventFilters();
	}

	public synchronized void resetSession() {
		generation++;
		fetchInProgress = false;
		appliedVersion = null;
		ticksRemaining = 0;
	}

	public synchronized void onGameTick() {
		if (!fetchInProgress && --ticksRemaining <= 0) fetchFiltersAsync();
	}

	/** A missing hint falls back to heartbeat-paced fetching during rollout/outages. */
	public synchronized void onServerVersion(String version) {
		if (version == null || !version.equals(appliedVersion)) fetchFiltersAsync();
	}

	public synchronized void fetchFiltersAsync() {
		if (fetchInProgress) return;
		fetchInProgress = true;
		final int requestGeneration = generation;
		Request request = new Request.Builder().url(FILTERS_URL).get()
			.addHeader("User-Agent", PluginVersion.userAgent()).build();
		httpClient.newCall(request).enqueue(new Callback() {
			@Override public void onFailure(Call call, IOException error) {
				synchronized (EventFilterManager.this) {
					if (requestGeneration != generation) return;
					fetchInProgress = false;
					ticksRemaining = RETRY_TICKS;
				}
				log.warn("Failed to fetch filters", error);
			}

			@Override public void onResponse(Call call, Response response) {
				try (Response closeable = response) {
					JsonObject json = response.isSuccessful() && response.body() != null
						? gson.fromJson(response.body().string(), JsonObject.class) : null;
					EventFilters parsed = json == null ? null : parseFilters(json);
					Runnable listener;
					synchronized (EventFilterManager.this) {
						if (requestGeneration != generation) return;
						fetchInProgress = false;
						ticksRemaining = RETRY_TICKS;
						if (parsed == null) return;
						filters = parsed;
						appliedVersion = response.header("X-Reval-Filters-Version");
						ticksRemaining = DAILY_TICKS;
						listener = onFiltersApplied;
					}
					if (listener != null) listener.run();
				} catch (Exception error) {
					onFailure(call, new IOException("Invalid filter response", error));
				}
			}
		});
	}

	/**
	 * Parse the filters JSON response
	 */
	private EventFilters parseFilters(JsonObject json) {
		EventFilters newFilters = new EventFilters();

		try {
			// A fresh EventFilters has empty lists, except the loot blacklist's defaults
			// Parse loot filters
			if (json.has("loot")) {
				JsonObject loot = json.getAsJsonObject("loot");

				if (loot.has("minValue")) {
					newFilters.lootMinValue = loot.get("minValue").getAsLong();
				}

				forEachIn(loot, "whitelist", item -> newFilters.lootWhitelist.add(item.getAsInt()));

				// Clear defaults and only use API values
				newFilters.lootBlacklist.clear();
				forEachIn(loot, "blacklist", item -> newFilters.lootBlacklist.add(item.getAsInt()));
			}

			// Parse detailed kill filters
			if (json.has("detailedKill")) {
				JsonObject detailedKill = json.getAsJsonObject("detailedKill");
				forEachIn(detailedKill, "npcIdWhitelist", id -> newFilters.detailedKillNpcIdWhitelist.add(id.getAsInt()));
				forEachIn(detailedKill, "npcIdBlacklist", id -> newFilters.detailedKillNpcIdBlacklist.add(id.getAsInt()));
				forEachIn(detailedKill, "npcNameWhitelist", name ->
					newFilters.detailedKillNpcNameWhitelist.add(name.getAsString().toLowerCase())
				);
			}

			// Parse inventory watches
			if (json.has("inventory")) {
				forEachIn(json.getAsJsonObject("inventory"), "watchItems", item -> {
					String name = item.getAsString().trim().toLowerCase();
					if (!name.isEmpty()) {
						newFilters.inventoryWatchItems.add(name);
						newFilters.inventoryWatchItemNames.put(name, item.getAsString().trim());
					}
				});
			}

			if (json.has("varbits")) {
				forEachIn(json.getAsJsonObject("varbits"), "watch", id -> {
					if (id.isJsonPrimitive() && id.getAsJsonPrimitive().isNumber()) {
						newFilters.varbitWatch.add(id.getAsInt());
					}
				});
				log.info("[Reval] watching varbits {}", newFilters.varbitWatch);
			}

			// Parse chat filters
			if (json.has("chat")) {
				forEachIn(json.getAsJsonObject("chat"), "patterns", pattern -> newFilters.chatPatterns.add(pattern.getAsString()));
			}

			// Parse event toggles; an omitted toggle keeps its default
			if (json.has("enabled")) {
				JsonObject enabled = json.getAsJsonObject("enabled");

				newFilters.lootEnabled = flag(enabled, "loot", newFilters.lootEnabled);
				newFilters.petEnabled = flag(enabled, "pet", newFilters.petEnabled);
				newFilters.questEnabled = flag(enabled, "quest", newFilters.questEnabled);
				newFilters.levelEnabled = flag(enabled, "level", newFilters.levelEnabled);
				newFilters.killCountEnabled = flag(enabled, "killCount", newFilters.killCountEnabled);
				newFilters.clueEnabled = flag(enabled, "clue", newFilters.clueEnabled);
				newFilters.diaryEnabled = flag(enabled, "diary", newFilters.diaryEnabled);
				newFilters.combatAchievementEnabled = flag(enabled, "combatAchievement", newFilters.combatAchievementEnabled);
				newFilters.collectionEnabled = flag(enabled, "collection", newFilters.collectionEnabled);
				newFilters.deathEnabled = flag(enabled, "death", newFilters.deathEnabled);
				newFilters.detailedKillEnabled = flag(enabled, "detailedKill", newFilters.detailedKillEnabled);
				newFilters.emoteEnabled = flag(enabled, "emote", newFilters.emoteEnabled);
				newFilters.chatEnabled = flag(enabled, "chat", newFilters.chatEnabled);
				newFilters.musicEnabled = flag(enabled, "music", newFilters.musicEnabled);
				newFilters.leaguesEnabled = flag(enabled, "leagues", newFilters.leaguesEnabled);
			}

			return newFilters;
		} catch (Exception e) {
			log.error("Error parsing filters JSON", e);
			return null;
		}
	}

	/** Runs {@code action} on each element of array {@code key}; an absent or non-array value does nothing. */
	private static void forEachIn(JsonObject parent, String key, Consumer<JsonElement> action) {
		if (parent.has(key) && parent.get(key).isJsonArray()) {
			parent.getAsJsonArray(key).forEach(action);
		}
	}

	private static boolean flag(JsonObject enabled, String key, boolean current) {
		return enabled.has(key) ? enabled.get(key).getAsBoolean() : current;
	}
}

package com.revalclan.util;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;

import java.util.ArrayList;
import java.util.List;

/** Null-tolerant accessors for loosely typed Gson objects (requirements, progress metadata). */
public final class Json {
	private Json() {
	}

	public static String str(JsonObject o, String key, String fallback) {
		JsonElement e = o == null ? null : o.get(key);
		if (e == null || e.isJsonNull()) return fallback;
		try {
			return e.getAsString();
		} catch (RuntimeException ex) {
			return fallback;
		}
	}

	public static int num(JsonObject o, String key, int fallback) {
		Double d = number(o, key);
		return d == null ? fallback : (int) Math.round(d);
	}

	public static Double number(JsonObject o, String key) {
		JsonElement e = o == null ? null : o.get(key);
		if (e == null || e.isJsonNull()) return null;
		try {
			return e.getAsDouble();
		} catch (RuntimeException ex) {
			return null;
		}
	}

	public static boolean bool(JsonObject o, String key) {
		JsonElement e = o == null ? null : o.get(key);
		try {
			return e != null && !e.isJsonNull() && e.getAsBoolean();
		} catch (RuntimeException ex) {
			return false;
		}
	}

	/** The array under {@code key}, or null when absent or not an array. */
	public static JsonArray array(JsonObject o, String key) {
		JsonElement e = o == null ? null : o.get(key);
		return e != null && e.isJsonArray() ? e.getAsJsonArray() : null;
	}

	/** String field {@code key} of every object in {@code array}, in order, skipping misses. */
	public static List<String> strings(JsonArray array, String key) {
		List<String> out = new ArrayList<>();
		if (array == null) return out;
		for (JsonElement e : array) {
			if (!e.isJsonObject()) continue;
			String v = str(e.getAsJsonObject(), key, null);
			if (v != null) out.add(v);
		}
		return out;
	}
}

package com.revalclan.util;

import java.text.DecimalFormat;
import java.text.DecimalFormatSymbols;
import java.util.Locale;

/** Formats integers with space grouping ("12 345") independent of the default locale. */
public final class NumberFmt {
	private NumberFmt() {
	}

	/** "1.5M", "12K", "900" — for GP amounts where the exact figure does not matter. */
	public static String compact(long value) {
		if (value >= 1_000_000_000L) return trimZero(value / 1_000_000_000d) + "B";
		if (value >= 1_000_000L) return trimZero(value / 1_000_000d) + "M";
		if (value >= 1_000L) return trimZero(value / 1_000d) + "K";
		return String.valueOf(value);
	}

	private static String trimZero(double d) {
		String s = String.format(Locale.ROOT, "%.1f", d);
		return s.endsWith(".0") ? s.substring(0, s.length() - 2) : s;
	}

	public static String group(long value) {
		DecimalFormatSymbols symbols = DecimalFormatSymbols.getInstance(Locale.ROOT);
		symbols.setGroupingSeparator(' ');
		return new DecimalFormat("#,##0", symbols).format(value);
	}
}

package com.revalclan.util;

import java.io.IOException;
import java.io.InputStream;
import java.util.Properties;
import lombok.extern.slf4j.Slf4j;

/**
 * The plugin's own version, read once from the {@code runelite-plugin.properties}
 * that Gradle copies into the jar. Every HTTP call to the Reval backend identifies
 * itself with {@link #userAgent()} so the server can tell which builds are running.
 */
@Slf4j
public final class PluginVersion {
	private static final String USER_AGENT_PREFIX = "RuneLite-RevalClan-Plugin/";
	private static final String RESOURCE = "/com/revalclan/runelite-plugin.properties";
	private static final String VERSION = load();

	private PluginVersion() {
	}

	public static String userAgent() {
		return USER_AGENT_PREFIX + VERSION;
	}

	private static String load() {
		try (InputStream in = PluginVersion.class.getResourceAsStream(RESOURCE)) {
			if (in != null) {
				Properties props = new Properties();
				props.load(in);
				String version = props.getProperty("version", "").trim();
				if (!version.isEmpty()) {
					return version;
				}
			}
		} catch (IOException e) {
			log.debug("Could not read plugin version", e);
		}
		return "unknown";
	}
}

package com.revalclan.util;

import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.gameval.VarbitID;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Death counts for one observed raid, independent of standalone death notifications.
 * A start message establishes coverage; enabling the plugin mid-raid does not.
 * ToB/ToA/Archive broadcast named deaths (including the game's logout penalties). CoX
 * only provides a reliable local-player signal: unseen teammates remain unknown.
 * Call on the client thread.
 */
@Singleton
public class RaidDeathTracker {
	static final String ARCHIVE_START_MESSAGE = "You enter the Archive...";

	private static final Pattern DEATH = Pattern.compile(
		"^(?:(?<name>.+) has (?<action>died|logged out)|You have (?<self>died))\\. "
			+ "(?<label>Death count|Total deaths): (?<total>[\\d,]+)\\.$");
	private static final Set<Integer> TOA_REGIONS = Set.of(
		14160, 15698, 15700, 14162, 14164, 15186, 15188, 14674, 14676, 15184, 15696, 14672);

	@Inject private Client client;

	private String raid;
	private String localName;
	private final Map<String, Integer> deaths = new HashMap<>();
	private boolean covered;
	private boolean completed;
	private int completionTick = -1;
	private int teamDeaths;
	private String lastDeathMessage;
	private int lastLocalDeathTick = -1;
	private int outsideTicks;

	/** @return true only for an explicit new-raid start. */
	public boolean onChatMessage(String message) {
		String started = null;
		if ("The raid has begun!".equals(message)) started = RaidPartyTracker.CHAMBERS_OF_XERIC;
		if (message.startsWith("You enter the Theatre of Blood")) started = RaidPartyTracker.THEATRE_OF_BLOOD;
		if (message.startsWith("You enter the Tombs of Amascut")) started = RaidPartyTracker.TOMBS_OF_AMASCUT;
		if (ARCHIVE_START_MESSAGE.equals(message)) started = RaidPartyTracker.FRACTURED_ARCHIVE;
		if (started != null) {
			reset();
			raid = started;
			Player local = client.getLocalPlayer();
			localName = local == null ? null : local.getName();
			covered = localName != null;
			return true;
		}
		if (raid == null || afterCompletionTick() || RaidPartyTracker.CHAMBERS_OF_XERIC.equals(raid)) return false;

		Matcher match = DEATH.matcher(message);
		if (!match.matches()) return false;
		boolean theatre = RaidPartyTracker.THEATRE_OF_BLOOD.equals(raid);
		if (theatre != "Death count".equals(match.group("label"))) return false;
		try {
			int total = Integer.parseInt(match.group("total").replace(",", ""));
			// The suffix is the TEAM total. It detects gaps/duplicate delivery; it
			// must never be reported as this player's personal death count.
			if (message.equals(lastDeathMessage)) return false;
			if (total != teamDeaths + 1) covered = false;
			teamDeaths = total;
			lastDeathMessage = message;
			String name = match.group("self") != null ? localName : match.group("name");
			if (name == null) {
				covered = false;
			} else {
				deaths.merge(RaidPartyTracker.nameKey(name), 1, Integer::sum);
			}
		} catch (NumberFormatException e) {
			covered = false;
		}
		return false;
	}

	public void onActorDeath(ActorDeath event) {
		if (!RaidPartyTracker.CHAMBERS_OF_XERIC.equals(raid) || !covered || afterCompletionTick()
			|| event.getActor() != client.getLocalPlayer() || !isInside(raid)) return;
		int tick = client.getTickCount();
		if (tick == lastLocalDeathTick) return;
		lastLocalDeathTick = tick;
		deaths.merge(RaidPartyTracker.nameKey(localName), 1, Integer::sum);
	}

	/** Stop a left/abandoned run without confusing room loads or dead spectating with a new run. */
	public void onGameTick() {
		if (raid == null) return;
		outsideTicks = isInside(raid) ? 0 : outsideTicks + 1;
		if (outsideTicks > 3) reset();
	}

	public void complete(String source) {
		if (source.equals(raid) && !completed) {
			completed = true;
			completionTick = client.getTickCount();
		}
	}

	private boolean afterCompletionTick() {
		return completed && client.getTickCount() > completionTick;
	}

	public boolean isCompleted(String source) {
		return completed && source.equals(raid);
	}

	/** Keys are canonical names. Absence means unknown, including CoX teammates. */
	public Map<String, Integer> countsFor(String source, List<String> names) {
		Map<String, Integer> counts = new HashMap<>();
		if (!covered || !source.equals(raid)) return counts;
		boolean chambers = RaidPartyTracker.CHAMBERS_OF_XERIC.equals(raid);
		for (String name : names) {
			String key = RaidPartyTracker.nameKey(name);
			if (!chambers || key.equals(RaidPartyTracker.nameKey(localName))) {
				counts.put(key, deaths.getOrDefault(key, 0));
			}
		}
		return counts;
	}

	public boolean isInside(String source) {
		if (RaidPartyTracker.CHAMBERS_OF_XERIC.equals(source)) {
			return client.getVarbitValue(VarbitID.RAIDS_CLIENT_INDUNGEON) == 1;
		}
		if (RaidPartyTracker.THEATRE_OF_BLOOD.equals(source)) {
			int status = client.getVarbitValue(VarbitID.TOB_CLIENT_PARTYSTATUS);
			return status == 2 || status == 3;
		}
		WorldView world = client.getTopLevelWorldView();
		if (RaidPartyTracker.FRACTURED_ARCHIVE.equals(source)) {
			int status = client.getVarbitValue(VarbitID.TFA_CLIENT_PARTYSTATUS);
			return (status == 2 || status == 3) && world != null && world.isInstance();
		}
		Player local = client.getLocalPlayer();
		return world != null && world.isInstance() && local != null
			&& TOA_REGIONS.contains(WorldPoint.fromLocalInstance(client, local.getLocalLocation()).getRegionID());
	}

	public void reset() {
		raid = null;
		localName = null;
		deaths.clear();
		covered = false;
		completed = false;
		completionTick = -1;
		teamDeaths = 0;
		lastDeathMessage = null;
		lastLocalDeathTick = -1;
		outsideTicks = 0;
	}
}

