import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * The party behind a raid's loot and completion count, with
 * each member marked as a Reval member or a guest.
 *
 * The party is read live and frozen, with known per-member deaths, at completion.
 * CoX/ToB/ToA use final-boss and completion snapshots. Their delayed rewards
 * retain those snapshots until an observation gap. ArchiveRoster owns native
 * Archive evidence, including its run boundaries and reward retention.
 * Call on the client thread.
 */
@Singleton
public class RaidPartyTracker {
	static final String CHAMBERS_OF_XERIC = "Chambers of Xeric";
	static final String THEATRE_OF_BLOOD = "Theatre of Blood";
	static final String TOMBS_OF_AMASCUT = "Tombs of Amascut";
	public static final String FRACTURED_ARCHIVE = "The Fractured Archive";

	/** First VarClientStr holding a ToB party member name (5 consecutive slots). */
	private static final int TOB_MEMBER_NAME_VARC = 330;
	private static final int TOB_PARTY_MAX_SIZE = 5;

	/** First VarClientStr holding a ToA party member name (8 consecutive slots). */
	private static final int TOA_MEMBER_NAME_VARC = 1099;
	private static final int TOA_PARTY_MAX_SIZE = 8;

	/** A saved party applies to rewards claimed up to this long after the final boss died. */
	static final long SAVED_PARTY_TTL_MS = 10 * 60_000L;

	/** Where a party was read. */
	public enum Origin { LIVE, FINAL_BOSS, COMPLETION }

	private static final Pattern COMPLETED = Pattern.compile(
		"^Your completed (.+?) count is: ([\\d,]+)\\.?$", Pattern.CASE_INSENSITIVE);

	@Inject private Client client;
	@Inject private RaidDeathTracker deathTracker;
	@Inject private ArchiveRoster archiveRoster;
	private final Map<String, Party> completedParties = new LinkedHashMap<>();

	private Party savedParty;
	private Party pendingCompletion;
	private long savedAtMs;

	/** Save the party when a raid's final boss dies. Not gated on membership: it only records. */
	public void onActorDeath(ActorDeath event) {
		deathTracker.onActorDeath(event);
		Actor actor = event.getActor();
		if (!(actor instanceof NPC)) return;
		String raid = raidForFinalBoss(actor.getName());
		if (raid == null) return;

		Party party = readParty(raid, Origin.FINAL_BOSS);
		if (party != null) {
			// An NPC name can be a Warden's earlier phase. Only the completion
			// message freezes death counts; this fallback saves names alone.
			savedParty = party.withDeaths(Map.of());
			savedAtMs = System.currentTimeMillis();
		}
	}

	/**
	 * The party for a raid loot or completion source, possibly with a mode suffix
	 * ("Theatre of Blood: Hard Mode"). Null when the source is not a raid or no
	 * party is known.
	 */
	public Party partyFor(String source) {
		String raid = raidOf(source);
		if (raid == null) return null;
		if (FRACTURED_ARCHIVE.equals(raid)) {
			Party party = archiveRoster.party(revalRoster());
			return party != null && party.origin == Origin.LIVE
				? party.withDeaths(deathTracker.countsFor(raid, party.names)) : party;
		}
		Party completed = completedParties.get(raid);
		if (completed != null && deathTracker.isCompleted(raid)) return completed;

		boolean insideRaid = deathTracker.isInside(raid);
		Party live = readParty(raid, Origin.LIVE);
		// Keep each raid's completed reward across scene changes and long breaks
		// in this login. An observation gap clears the cache: an offline raid
		// could otherwise leave us annotating a new reward with an old count.
		if (!insideRaid) {
			if (completed != null) return completed;
			if (live != null) live = live.withDeaths(Map.of());
		}
		return choose(raid, live, insideRaid, savedParty,
			System.currentTimeMillis() - savedAtMs);
	}

	/** Observe game messages before notification settings or clan validation can filter them. */
	public void onChatMessage(ChatMessageType type, String rawMessage) {
		if (type != ChatMessageType.GAMEMESSAGE && type != ChatMessageType.FRIENDSCHATNOTIFICATION
			&& type != ChatMessageType.SPAM && type != ChatMessageType.ENGINE) return;
		String message = sanitize(rawMessage);
		if (deathTracker.onChatMessage(message)) {
			savedParty = null;
			savedAtMs = 0;
			if (RaidDeathTracker.ARCHIVE_START_MESSAGE.equals(message)) archiveRoster.reset();
		}
		String raid = null;
		Matcher completed = COMPLETED.matcher(message);
		if (completed.find()) raid = raidOf(completed.group(1));
		if (FRACTURED_ARCHIVE.equals(raid)) {
			try {
				Party party = archiveRoster.complete(Integer.parseInt(completed.group(2).replace(",", "")));
				deathTracker.complete(raid);
				if (party != null) {
					party.updateDeaths(deathTracker.countsFor(raid, party.names));
					pendingCompletion = party;
				}
			} catch (NumberFormatException ignored) {}
			return;
		}
		if (message.startsWith("Congratulations - your raid is complete!")) raid = CHAMBERS_OF_XERIC;
		if (message.startsWith("Challenge complete: The Wardens.")) raid = TOMBS_OF_AMASCUT;
		if (raid == null) return;
		if (deathTracker.isCompleted(raid) && completedParties.containsKey(raid)) return;

		Party party = readParty(raid, Origin.COMPLETION);
		if (party == null && savedParty != null && savedParty.raid.equals(raid)
			&& System.currentTimeMillis() - savedAtMs <= SAVED_PARTY_TTL_MS) {
			party = new Party(raid, Origin.COMPLETION, savedParty.names, savedParty.revalMembers,
				savedParty.deaths).withDeaths(deathTracker.countsFor(raid, savedParty.names));
		}
		deathTracker.complete(raid);
		if (party == null) {
			completedParties.remove(raid);
			if (savedParty != null && savedParty.raid.equals(raid)) savedParty = null;
		} else {
			savedParty = party;
			savedAtMs = System.currentTimeMillis();
			completedParties.put(raid, party);
			pendingCompletion = party;
		}
	}

	public void onGameTick() {
		archiveRoster.observe();
		// Finish the server tick before freezing: a final death and completion
		// can arrive in either order. Buffered loot/KC retain this same snapshot.
		if (pendingCompletion != null) {
			if (deathTracker.isCompleted(pendingCompletion.raid)) {
				pendingCompletion.updateDeaths(deathTracker.countsFor(pendingCompletion.raid, pendingCompletion.names));
			}
			pendingCompletion = null;
		}
		deathTracker.onGameTick();
	}

	public void onGameStateChanged(GameState state) {
		if (state == GameState.CONNECTION_LOST || state == GameState.HOPPING || state == GameState.LOGIN_SCREEN) reset();
	}

	/** Forget observation after logout/plugin stop; a later unmatched reward has unknown counts. */
	public void reset() {
		savedParty = null;
		pendingCompletion = null;
		savedAtMs = 0;
		deathTracker.reset();
		completedParties.clear();
		archiveRoster.reset();
	}

	/**
	 * Inside the raid the live party is the truth. Outside it, a party saved at
	 * this raid's final boss within the TTL wins over whatever the interface
	 * still holds.
	 */
	static Party choose(String raid, Party live, boolean insideRaid, Party saved, long savedAgeMs) {
		if (insideRaid && live != null) return live;
		boolean savedApplies = saved != null && saved.raid.equals(raid)
			&& savedAgeMs >= 0 && savedAgeMs <= SAVED_PARTY_TTL_MS;
		return savedApplies ? saved : live;
	}

	/** The raid a loot or completion source belongs to, or null. */
	public static String raidOf(String source) {
		if (source == null) return null;
		String name = sanitize(source).toLowerCase(Locale.ROOT);
		if (name.startsWith(CHAMBERS_OF_XERIC.toLowerCase(Locale.ROOT))) return CHAMBERS_OF_XERIC;
		if (name.startsWith(THEATRE_OF_BLOOD.toLowerCase(Locale.ROOT))) return THEATRE_OF_BLOOD;
		if (name.startsWith(TOMBS_OF_AMASCUT.toLowerCase(Locale.ROOT))) return TOMBS_OF_AMASCUT;
		if (name.equals(FRACTURED_ARCHIVE.toLowerCase(Locale.ROOT)) || name.equals("fractured archive")) return FRACTURED_ARCHIVE;
		return null;
	}

	/** The raid whose last boss this NPC is, or null. */
	static String raidForFinalBoss(String npcName) {
		switch (sanitize(npcName).replace('’', '\'')) {
			case "Great Olm":
				return CHAMBERS_OF_XERIC;
			case "Verzik Vitur":
				return THEATRE_OF_BLOOD;
			case "Tumeken's Warden":
			case "Elidinis' Warden":
				return TOMBS_OF_AMASCUT;
			default:
				return null;
		}
	}

	private Party readParty(String raid, Origin origin) {
		List<String> names;
		if (CHAMBERS_OF_XERIC.equals(raid)) {
			names = chambersNames();
		} else if (THEATRE_OF_BLOOD.equals(raid)) {
			names = varcNames(TOB_MEMBER_NAME_VARC, TOB_PARTY_MAX_SIZE);
		} else if (TOMBS_OF_AMASCUT.equals(raid)) {
			names = varcNames(TOA_MEMBER_NAME_VARC, TOA_PARTY_MAX_SIZE);
		} else {
			return null;
		}
		return names.isEmpty() ? null : Party.of(raid, origin, names, revalRoster())
			.withDeaths(deathTracker.countsFor(raid, names));
	}

	/**
	 * CoX lists the whole party in the raid side panel. When that widget is not
	 * loaded, the players in the raid instance stand in for it.
	 */
	private List<String> chambersNames() {
		List<String> names = new ArrayList<>();
		Widget list = client.getWidget(InterfaceID.RaidsSidepanel.LIST);
		Widget[] children = list == null ? null : list.getChildren();
		if (children != null) {
			for (Widget child : children) {
				if (child != null) addName(names, child.getName());
			}
		}
		if (!names.isEmpty()) return names;

		WorldView world = client.getTopLevelWorldView();
		if (world != null && world.isInstance()) {
			for (Player player : world.players()) {
				if (player != null) addName(names, player.getName());
			}
		}
		return names;
	}

	private List<String> varcNames(int initialVarcId, int maxSize) {
		List<String> names = new ArrayList<>(maxSize);
		for (int i = 0; i < maxSize; i++) {
			addName(names, client.getVarcStrValue(initialVarcId + i));
		}
		return names;
	}

	/**
	 * Name keys of every Reval member, or null when the loaded clan settings are
	 * not Reval's. Guests are never in the clan settings, so absence from a
	 * loaded roster means guest.
	 */
	private Set<String> revalRoster() {
		if (ClanValidator.isCheckDisabled()) return null;
		ClanSettings settings = client.getClanSettings();
		if (settings == null || !ClanValidator.REQUIRED_CLAN_NAME.equalsIgnoreCase(settings.getName())) return null;
		List<ClanMember> members = settings.getMembers();
		if (members == null || members.isEmpty()) return null;

		Set<String> keys = new HashSet<>();
		for (ClanMember member : members) {
			if (member != null && member.getName() != null) keys.add(nameKey(member.getName()));
		}
		return keys;
	}

	private static void addName(List<String> names, String raw) {
		String name = sanitize(raw);
		if (name.isEmpty()) return;
		for (String existing : names) {
			if (existing.equalsIgnoreCase(name)) return;
		}
		names.add(name);
	}

	private static String sanitize(String raw) {
		if (raw == null || raw.isEmpty()) return "";
		return Text.removeTags(raw).replace(' ', ' ').trim();
	}

	/** RuneScape treats space, underscore and hyphen in a name as the same character. */
	static String nameKey(String name) {
		return sanitize(name).toLowerCase(Locale.ROOT).replace('_', ' ').replace('-', ' ');
	}

	/** One raid party: its members in party order and whether each is in Reval. */
	public static final class Party {
		final String raid;
		final Origin origin;
		final List<String> names;
		/** Parallel to names; a null entry means the Reval roster was not loaded. */
		final List<Boolean> revalMembers;
		/** Parallel to names; null means the full raid count is unknown. */
		final List<Integer> deaths;
		private final Integer size;
		private final Boolean rosterComplete;

		private Party(String raid, Origin origin, List<String> names, List<Boolean> revalMembers, List<Integer> deaths) {
			this(raid, origin, names, revalMembers, deaths, null, null);
		}

		private Party(String raid, Origin origin, List<String> names, List<Boolean> revalMembers, List<Integer> deaths,
			Integer size, Boolean rosterComplete) {
			this.raid = raid;
			this.origin = origin;
			this.names = names;
			this.revalMembers = revalMembers;
			this.deaths = deaths;
			this.size = size;
			this.rosterComplete = rosterComplete;
		}

		static Party of(String raid, Origin origin, List<String> names, Set<String> revalRoster) {
			List<Boolean> flags = new ArrayList<>(names.size());
			List<Integer> deaths = new ArrayList<>(names.size());
			for (String name : names) {
				flags.add(revalRoster == null ? null : revalRoster.contains(nameKey(name)));
				deaths.add(null);
			}
			return new Party(raid, origin, names, flags, deaths);
		}

		/** Share completion deaths so the final-tick update reaches every membership view. */
		Party withClanRoster(Set<String> revalRoster) {
			List<Boolean> flags = new ArrayList<>(names.size());
			for (String name : names) flags.add(revalRoster == null ? null : revalRoster.contains(nameKey(name)));
			return new Party(raid, origin, names, flags, deaths, size, rosterComplete);
		}

		private Party withDeaths(Map<String, Integer> counts) {
			List<Integer> values = new ArrayList<>(names.size());
			for (String name : names) values.add(counts.get(nameKey(name)));
			return new Party(raid, origin, names, revalMembers, values, size, rosterComplete);
		}

		Party withRosterEvidence(int size, boolean complete) {
			return new Party(raid, origin, names, revalMembers, deaths, size, complete);
		}

		private void updateDeaths(Map<String, Integer> counts) {
			for (int i = 0; i < names.size(); i++) deaths.set(i, counts.get(nameKey(names.get(i))));
		}

		/**
		 * Adds {@code partyMembers} (the names, as the backend has always received
		 * them) and {@code party}: where the party was read and each member's
		 * {@code clanMember} flag, left out when the Reval roster was not loaded.
		 */
		public void addTo(Map<String, Object> data) {
			data.put("partyMembers", names);

			List<Map<String, Object>> members = new ArrayList<>(names.size());
			for (int i = 0; i < names.size(); i++) {
				Map<String, Object> member = new LinkedHashMap<>();
				member.put("name", names.get(i));
				if (revalMembers.get(i) != null) member.put("clanMember", revalMembers.get(i));
				if (deaths.get(i) != null) member.put("deaths", deaths.get(i));
				members.add(member);
			}

			Map<String, Object> party = new LinkedHashMap<>();
			party.put("origin", origin.name().toLowerCase(Locale.ROOT));
			party.put("members", members);
			if (size != null) party.put("size", size);
			if (rosterComplete != null) party.put("rosterComplete", rosterComplete);
			data.put("party", party);
		}
	}
}

package com.revalclan.util;

import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemStack;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.Collection;
import java.util.Locale;
import java.util.Map;
import java.util.StringJoiner;
import java.util.TreeMap;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Keeps a ToB, ToA or Fractured Archive reward from being reported again when its chest is reopened.
 *
 * RuneLite's loot tracker reports a raid chest each time it opens after the player
 * has moved between an instance and the normal world (runelite/runelite#18427). A
 * reward opened inside the raid and claimed later from the chest outside it (opposite
 * the Ver Sinhaza bank, or the rewards niche in the ToA lobby), or reopened after a
 * trip through a house, is reported again with whatever is left in it. Until the raid
 * is completed again the chest can only lose items, so a chest holding nothing beyond
 * the reward already reported is that same reward.
 *
 * The reported reward is kept in the RS profile, so a reward left in the chest across
 * a logout or a client restart still counts once. Call on the client thread.
 */
@Singleton
public class RaidRewardLedger {
	private static final String CONFIG_GROUP = "revalclan";
	private static final String CONFIG_KEY_PREFIX = "raidReward_";

	/** Completed-count messages resolve through the same raid identity as the reward source. */
	private static final Pattern COMPLETION = Pattern.compile(
		"^Your completed (.+?) count is: [\\d,]+\\b", Pattern.CASE_INSENSITIVE);

	@Inject private ConfigManager configManager;

	/** A completed raid leaves a new reward in its chest: forget the one reported before. */
	public void onGameMessage(String message) {
		String raid = completedRaid(message);
		if (raid != null) {
			configManager.unsetRSProfileConfiguration(CONFIG_GROUP, key(raid));
		}
	}

	/**
	 * Record a loot report. False only for a guarded raid chest holding nothing beyond the
	 * reward reported since the raid was last completed; loot from anything else is always
	 * new and is not recorded.
	 */
	public boolean record(String source, Collection<ItemStack> items) {
		String raid = guardedRaid(source);
		if (raid == null) return true;

		Map<Integer, Integer> chest = totals(items);
		if (within(chest, decode(configManager.getRSProfileConfiguration(CONFIG_GROUP, key(raid))))) return false;

		configManager.setRSProfileConfiguration(CONFIG_GROUP, key(raid), encode(chest));
		return true;
	}

	/** The raid a loot source is the reward chest of, when that chest can be reopened outside the raid. */
	static String guardedRaid(String source) {
		String raid = RaidPartyTracker.raidOf(source);
		// Chambers of Xeric has no reward chest outside the raid
		return RaidPartyTracker.CHAMBERS_OF_XERIC.equals(raid) ? null : raid;
	}

	/** The raid a "Your completed ... count is" message completes, or null. */
	static String completedRaid(String message) {
		if (message == null) return null;
		Matcher matcher = COMPLETION.matcher(message);
		return matcher.find() ? guardedRaid(matcher.group(1)) : null;
	}

	/** Item id → quantity, merging split stacks and skipping empty slots. */
	static Map<Integer, Integer> totals(Collection<ItemStack> items) {
		Map<Integer, Integer> totals = new TreeMap<>();
		for (ItemStack item : items) {
			if (item.getId() > 0 && item.getQuantity() > 0) {
				totals.merge(item.getId(), item.getQuantity(), Integer::sum);
			}
		}
		return totals;
	}

	/** Whether the reported reward covers every item in the chest, in quantity. */
	static boolean within(Map<Integer, Integer> chest, Map<Integer, Integer> reported) {
		for (Map.Entry<Integer, Integer> item : chest.entrySet()) {
			if (item.getValue() > reported.getOrDefault(item.getKey(), 0)) return false;
		}
		return true;
	}

	/** "id:quantity,id:quantity" in id order. */
	static String encode(Map<Integer, Integer> totals) {
		StringJoiner joined = new StringJoiner(",");
		for (Map.Entry<Integer, Integer> item : new TreeMap<>(totals).entrySet()) {
			joined.add(item.getKey() + ":" + item.getValue());
		}
		return joined.toString();
	}

	/** The totals an encoded reward holds; empty when there is none or it cannot be read. */
	static Map<Integer, Integer> decode(String encoded) {
		Map<Integer, Integer> totals = new TreeMap<>();
		if (encoded == null || encoded.isEmpty()) return totals;
		try {
			for (String entry : encoded.split(",")) {
				int colon = entry.indexOf(':');
				totals.merge(Integer.parseInt(entry.substring(0, colon)), Integer.parseInt(entry.substring(colon + 1)), Integer::sum);
			}
		} catch (RuntimeException e) {
			// Unreadable: report the next chest rather than risk swallowing a new reward
			totals.clear();
		}
		return totals;
	}

	private static String key(String raid) {
		return CONFIG_KEY_PREFIX + raid.toLowerCase(Locale.ROOT).replace(' ', '_');
	}
}

package com.revalclan.util;

/**
 * Formats web rank slugs (e.g. "red_topaz") as in-game rank titles ("Red Topaz").
 * Rank names on the backend are the in-game clan ranks since the single-line
 * rank rework, so this is the only mapping the plugin needs.
 */
public final class RankNames {
	private RankNames() {}

	public static String display(String rank) {
		if (rank == null || rank.isEmpty()) return "?";
		StringBuilder out = new StringBuilder();
		for (String word : rank.split("[_\\s]+")) {
			if (word.isEmpty()) continue;
			if (out.length() > 0) out.append(' ');
			out.append(Character.toUpperCase(word.charAt(0)));
			if (word.length() > 1) out.append(word.substring(1).toLowerCase());
		}
		return out.length() > 0 ? out.toString() : rank;
	}
}

package com.revalclan.util;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.ui.DrawManager;

import javax.imageio.IIOImage;
import javax.imageio.ImageIO;
import javax.imageio.ImageWriteParam;
import javax.imageio.ImageWriter;
import javax.imageio.stream.ImageOutputStream;
import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ScheduledExecutorService;

@Slf4j
@Singleton
public class ScreenshotService {
	private static final float JPEG_QUALITY = 0.92f;
	private static final int MAX_WIDTH = 1600;

	@Inject private DrawManager drawManager;
	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private ScheduledExecutorService executor;

	/** JPEG bytes of the next frame, or null when the capture failed. */
	public CompletableFuture<byte[]> captureScreenshot() {
		CompletableFuture<byte[]> result = new CompletableFuture<>();

		clientThread.invoke(() -> {
			Widget chat = client.getWidget(InterfaceID.Chatbox.CHATAREA);
			Widget pm = client.getWidget(InterfaceID.PmChat.CONTAINER);

			boolean chatWasVisible = chat != null && !chat.isHidden();
			boolean pmWasVisible = pm != null && !pm.isHidden();

			if (chatWasVisible) chat.setHidden(true);
			if (pmWasVisible) pm.setHidden(true);

			drawManager.requestNextFrameListener(image -> {
				if (chatWasVisible || pmWasVisible) {
					clientThread.invoke(() -> {
						if (chatWasVisible && chat != null) chat.setHidden(false);
						if (pmWasVisible && pm != null) pm.setHidden(false);
						return true;
					});
				}

				executor.submit(() -> {
					if (image == null) {
						result.complete(null);
						return;
					}
					try {
						BufferedImage screenshot = toBufferedImage(image);
						screenshot = resizeIfNeeded(screenshot);
						result.complete(compress(screenshot));
					} catch (Exception e) {
						log.error("Error processing screenshot", e);
						result.complete(null);
					}
				});
			});

			return true;
		});

		return result;
	}

	/**
	 * Converts an Image to a BufferedImage if it isn't one already.
	 */
	private BufferedImage toBufferedImage(Image image) {
		if (image instanceof BufferedImage) {
			return (BufferedImage) image;
		}

		BufferedImage buffered = new BufferedImage(
			image.getWidth(null), image.getHeight(null), BufferedImage.TYPE_INT_RGB);
		Graphics2D g = buffered.createGraphics();
		g.drawImage(image, 0, 0, null);
		g.dispose();
		return buffered;
	}

	/**
	 * Downsizes the image if wider than MAX_WIDTH to keep payload small.
	 */
	private BufferedImage resizeIfNeeded(BufferedImage image) {
		if (image.getWidth() <= MAX_WIDTH) {
			return image;
		}

		double scale = (double) MAX_WIDTH / image.getWidth();
		int newHeight = (int) (image.getHeight() * scale);

		BufferedImage resized = new BufferedImage(MAX_WIDTH, newHeight, BufferedImage.TYPE_INT_RGB);
		Graphics2D g = resized.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BICUBIC);
		g.drawImage(image, 0, 0, MAX_WIDTH, newHeight, null);
		g.dispose();
		return resized;
	}

	/**
	 * Compresses the image as JPEG.
	 */
	private byte[] compress(BufferedImage image) throws Exception {
		ByteArrayOutputStream baos = new ByteArrayOutputStream(65536);

		ImageWriter writer = ImageIO.getImageWritersByFormatName("jpeg").next();
		ImageWriteParam param = writer.getDefaultWriteParam();
		param.setCompressionMode(ImageWriteParam.MODE_EXPLICIT);
		param.setCompressionQuality(JPEG_QUALITY);

		try (ImageOutputStream ios = ImageIO.createImageOutputStream(baos)) {
			writer.setOutput(ios);
			writer.write(null, new IIOImage(image, null, null), param);
		} finally {
			writer.dispose();
		}

		byte[] bytes = baos.toByteArray();
		log.debug("Screenshot captured: {}x{}, {} KB", image.getWidth(), image.getHeight(), bytes.length / 1024);

		return bytes;
	}
}

package com.revalclan.util;

import net.runelite.client.game.SpriteManager;
import net.runelite.client.util.ImageUtil;

import javax.swing.ImageIcon;
import javax.swing.JLabel;
import javax.swing.SwingUtilities;
import java.awt.image.BufferedImage;
import java.util.function.Consumer;

/** Loads game cache sprites into Swing components, aspect-fit into a square box. */
public final class SpriteIcons {
	private SpriteIcons() {
	}

	/** Load a sprite async and hand the fitted icon to {@code consumer} on the EDT. */
	public static void load(SpriteManager spriteManager, int spriteId, int size, Consumer<ImageIcon> consumer) {
		if (spriteManager == null || consumer == null) {
			return;
		}
		spriteManager.getSpriteAsync(spriteId, 0, sprite -> {
			if (sprite != null) {
				SwingUtilities.invokeLater(() -> consumer.accept(fit(sprite, size)));
			}
		});
	}

	/** Load a sprite async and set it on a label. */
	public static void apply(SpriteManager spriteManager, int spriteId, JLabel target, int size) {
		if (target == null) {
			return;
		}
		load(spriteManager, spriteId, size, target::setIcon);
	}

	/** Scale preserving aspect ratio, then pad onto a size x size canvas. */
	public static ImageIcon fit(BufferedImage image, int size) {
		BufferedImage scaled = image;
		if (scaled.getWidth() > size || scaled.getHeight() > size) {
			double scale = Math.min((double) size / scaled.getWidth(), (double) size / scaled.getHeight());
			scaled = ImageUtil.resizeImage(scaled,
				Math.max(1, (int) Math.round(scaled.getWidth() * scale)),
				Math.max(1, (int) Math.round(scaled.getHeight() * scale)));
		}
		return new ImageIcon(ImageUtil.resizeCanvas(scaled, size, size));
	}
}

package com.revalclan.util;

import com.google.gson.JsonObject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.Consumer;

/**
 * Sync-state fingerprint handshake: hashes quests + miniquests, diaries and
 * CAs (clog and KCs deliberately excluded — no real clog scan exists at
 * boundaries, KCs change constantly). When the hash matches the last server
 * ack, boundary payloads go slim. An ack with stale=true clears the stored
 * fingerprint and requests a full repair SYNC.
 */
@Slf4j
@Singleton
public class SyncStateManager {
	private static final String CONFIG_GROUP = "revalclan";
	private static final String CONFIG_KEY_PREFIX = "syncFingerprint_";

	@Inject private ConfigManager configManager;

	/** Set from the webhook response thread; consumed on the game-tick thread */
	private final AtomicBoolean fullSyncRequested = new AtomicBoolean(false);

	/** Canonical state fingerprint; null when the data is too incomplete to hash safely. */
	@SuppressWarnings("unchecked")
	public String computeFingerprint(Map<String, Object> data) {
		try {
			StringBuilder canonical = new StringBuilder(16384);

			// Quests: sorted name=state (quests, then miniquests) + quest points
			Map<String, Object> quests = (Map<String, Object>) data.get("quests");
			canonical.append("quests|");
			if (quests != null) {
				appendSorted(canonical, quests.get("questStates"));
				Object miniquestStates = quests.get("miniquestStates");
				if (miniquestStates instanceof Map) {
					canonical.append("mini|");
					appendSorted(canonical, miniquestStates);
				}
				canonical.append("qp=").append(quests.get("questPoints"));
			}

			// Diaries: sorted area=easy,medium,hard,elite
			Map<String, Object> diaries = (Map<String, Object>) data.get("achievementDiaries");
			canonical.append("|diaries|");
			if (diaries != null && diaries.get("progress") instanceof Map) {
				Map<String, Object> progress = new TreeMap<>((Map<String, Object>) diaries.get("progress"));
				for (Map.Entry<String, Object> e : progress.entrySet()) {
					canonical.append(e.getKey()).append('=');
					if (e.getValue() instanceof Map) {
						Map<String, Object> tiers = (Map<String, Object>) e.getValue();
						canonical.append(tiers.get("easy")).append(',')
							.append(tiers.get("medium")).append(',')
							.append(tiers.get("hard")).append(',')
							.append(tiers.get("elite"));
					}
					canonical.append(';');
				}
			}

			// CAs: sorted completed task names + total points (a present `completed`
			// flag is honoured, but the slim shape omits it)
			Map<String, Object> cas = (Map<String, Object>) data.get("combatAchievements");
			canonical.append("|cas|");
			if (cas != null) {
				Object allTasks = cas.get("allTasks");
				if (allTasks instanceof List) {
					TreeMap<String, Boolean> completedNames = new TreeMap<>();
					for (Object taskObj : (List<Object>) allTasks) {
						if (taskObj instanceof Map) {
							Map<String, Object> task = (Map<String, Object>) taskObj;
							Object completed = task.get("completed");
							if (completed == null || Boolean.TRUE.equals(completed)) {
								completedNames.put(String.valueOf(task.get("name")), true);
							}
						}
					}
					for (String name : completedNames.keySet()) {
						canonical.append(name).append(';');
					}
				}
				canonical.append("pts=").append(cas.get("totalPoints"));
			}

			// Collection log and KCs are deliberately NOT hashed (see class javadoc)

			return sha256Hex(canonical.toString());
		} catch (Exception e) {
			log.warn("Failed to compute sync fingerprint: {}", e.getMessage());
			return null;
		}
	}

	/** {@code key=value;} per entry in key order; nothing when {@code states} is not a map. */
	@SuppressWarnings("unchecked")
	private static void appendSorted(StringBuilder canonical, Object states) {
		if (!(states instanceof Map)) return;
		for (Map.Entry<String, Object> e : new TreeMap<>((Map<String, Object>) states).entrySet()) {
			canonical.append(e.getKey()).append('=').append(e.getValue()).append(';');
		}
	}

	public String getAckedFingerprint(long accountHash) {
		return configManager.getConfiguration(CONFIG_GROUP, CONFIG_KEY_PREFIX + accountHash);
	}

	/** Response consumer recording the server's fingerprint ack for this account. */
	public Consumer<JsonObject> ackHandler(long accountHash) {
		return response -> handleSyncAckResponse(response, accountHash);
	}

	/** Handles the `sync` object from a webhook response. HTTP thread — never touch the client. */
	public void handleSyncAckResponse(JsonObject response, long accountHash) {
		try {
			if (response == null || !response.has("sync") || !response.get("sync").isJsonObject()) return;
			JsonObject sync = response.getAsJsonObject("sync");

			boolean stale = sync.has("stale") && !sync.get("stale").isJsonNull() && sync.get("stale").getAsBoolean();
			if (stale) {
				try {
					configManager.unsetConfiguration(CONFIG_GROUP, CONFIG_KEY_PREFIX + accountHash);
				} catch (Exception ignored) {}
				fullSyncRequested.set(true);
				log.info("Sync fingerprint stale — full sync requested");
				return;
			}

			if (sync.has("fingerprint") && !sync.get("fingerprint").isJsonNull()) {
				configManager.setConfiguration(CONFIG_GROUP, CONFIG_KEY_PREFIX + accountHash, sync.get("fingerprint").getAsString());
			}
		} catch (Exception e) {
			log.warn("Failed to handle sync ack: {}", e.getMessage());
		}
	}

	/** Consumed from the game-tick loop */
	public boolean consumeFullSyncRequest() {
		return fullSyncRequested.getAndSet(false);
	}

	private static String sha256Hex(String input) throws Exception {
		MessageDigest digest = MessageDigest.getInstance("SHA-256");
		byte[] hash = digest.digest(input.getBytes(StandardCharsets.UTF_8));
		StringBuilder hex = new StringBuilder(hash.length * 2);
		for (byte b : hash) {
			hex.append(Character.forDigit((b >> 4) & 0xF, 16)).append(Character.forDigit(b & 0xF, 16));
		}
		return hex.toString();
	}
}

package com.revalclan.util;

import java.awt.Color;

/** Event team colours: parsing the backend's hex, and keeping them readable on the dark panel. */
public final class TeamColor {
	/** Teams whose colour is unset get the backend's default gray. */
	public static final Color FALLBACK = new Color(0x888888);

	private TeamColor() {
	}

	public static Color parse(String hex) {
		if (hex == null || hex.isEmpty()) return FALLBACK;
		try {
			return Color.decode(hex);
		} catch (NumberFormatException e) {
			return FALLBACK;
		}
	}

	/** Near-white and near-black team colours vanish on the panel background; nudge them. */
	public static Color onDarkPanel(Color c) {
		int sum = c.getRed() + c.getGreen() + c.getBlue();
		if (sum > 720) return new Color(220, 220, 220);
		if (sum < 60) return new Color(140, 140, 140);
		return c;
	}
}

package com.revalclan.util;

import java.awt.FontMetrics;
import java.util.ArrayList;
import java.util.List;

/** Greedy word wrap measured with the real font, for plain (non-HTML) labels. */
public final class TextWrap {
	private TextWrap() {
	}

	/** Lines of at most {@code width} pixels; a single overlong word stays on its own line. */
	public static List<String> wrap(String text, FontMetrics fm, int width) {
		List<String> lines = new ArrayList<>();
		if (text == null || text.trim().isEmpty()) return lines;
		StringBuilder line = new StringBuilder();
		for (String word : text.trim().split("\\s+")) {
			String candidate = line.length() == 0 ? word : line + " " + word;
			if (fm.stringWidth(candidate) <= width || line.length() == 0) {
				line.setLength(0);
				line.append(candidate);
			} else {
				lines.add(line.toString());
				line.setLength(0);
				line.append(word);
			}
		}
		if (line.length() > 0) lines.add(line.toString());
		return lines;
	}
}

package com.revalclan.util;

import javax.imageio.ImageIO;
import javax.inject.Singleton;
import javax.swing.*;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.net.URL;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

@Singleton
public class UIAssetLoader {
    private static final String ASSETS_BASE_PATH = "/com/revalclan/ui/assets/";

    private final Map<String, ImageIcon> iconCache = new ConcurrentHashMap<>();
    private final Map<String, BufferedImage> imageCache = new ConcurrentHashMap<>();

    /**
     * Load a BufferedImage from assets directory.
     * Results are cached for efficiency.
     * 
     * @param filename The filename (e.g., "reval.png")
     * @return The BufferedImage, or null if not found
     */
    public BufferedImage getImage(String filename) {
      if (filename == null || filename.isEmpty()) {
        return null;
      }

      String normalizedFilename = normalizeFilename(filename);

      BufferedImage cached = imageCache.get(normalizedFilename);
      if (cached != null) {
        return cached;
      }

      String resourcePath = ASSETS_BASE_PATH + normalizedFilename;
      URL imageUrl = getClass().getResource(resourcePath);

      if (imageUrl == null) {
        return null;
      }

      try {
        BufferedImage image = ImageIO.read(imageUrl);
        if (image != null) {
          imageCache.put(normalizedFilename, image);
        }
        return image;
      } catch (IOException e) {
        return null;
      }
    }

    /**
     * Load an icon from assets directory and scale it to the specified size.
     * Results are cached for efficiency.
     * 
     * @param filename The filename (e.g., "checkmark.png", "info.png")
     * @param size The target size (width and height)
     * @return The scaled ImageIcon, or null if not found
     */
    public ImageIcon getIcon(String filename, int size) {
      if (filename == null || filename.isEmpty()) {
        return null;
      }

      String cacheKey = normalizeFilename(filename) + "_" + size;

      ImageIcon cached = iconCache.get(cacheKey);
      if (cached != null) {
        return cached;
      }

      // Shares getImage's cache, so an image loaded at one size is reused for others
      BufferedImage image = getImage(filename);
      if (image == null) {
        return null;
      }

      Image scaled = image.getScaledInstance(size, size, Image.SCALE_SMOOTH);
      ImageIcon icon = new ImageIcon(scaled);
      iconCache.put(cacheKey, icon);

      return icon;
    }

    /** Bare file name (anything up to the last '/' dropped), with ".png" added when missing. */
    private String normalizeFilename(String filename) {
      String normalized = filename.substring(filename.lastIndexOf('/') + 1);
      return normalized.endsWith(".png") ? normalized : normalized + ".png";
    }
}

package com.revalclan.util;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import lombok.extern.slf4j.Slf4j;
import okhttp3.*;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.Map;
import java.util.function.Consumer;
import java.util.zip.GZIPOutputStream;

@Slf4j
@Singleton
public class WebhookService {
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	private static final MediaType GZIP = MediaType.parse("application/gzip");
	private static final MediaType JPEG = MediaType.parse("image/jpeg");
	private static final String WEBHOOK_URL = "https://api.revalosrs.ee/reval-webhook";

	@Inject
	private OkHttpClient httpClient;

	@Inject
	private Gson gson;

	/**
	 * Async send; hands the parsed JSON response to the consumer on success
	 * (null consumer = fire and forget).
	 * Consumer runs on the HTTP thread — do not touch the client from it.
	 */
	public void sendDataAsync(Map<String, Object> data, Consumer<JsonObject> onResponse) {
		sendDataAsync(data, null, onResponse);
	}

	/**
	 * Async send with an optional JPEG screenshot. Without one the body is the
	 * gzipped JSON. With one the request is multipart: the gzipped JSON in a
	 * {@code payload} part and the image as raw bytes in a {@code screenshot}
	 * part, which saves the third that base64 inside the JSON would add.
	 *
	 * @param data The event data
	 * @param screenshotJpeg JPEG bytes, or null
	 * @param onResponse Optional consumer for the parsed JSON response body
	 */
	public void sendDataAsync(Map<String, Object> data, byte[] screenshotJpeg, Consumer<JsonObject> onResponse) {
		try {
			byte[] payload = gzip(gson.toJson(data).getBytes(StandardCharsets.UTF_8));

			Request.Builder request = new Request.Builder()
				.url(WEBHOOK_URL)
				.addHeader("User-Agent", PluginVersion.userAgent());

			if (screenshotJpeg == null) {
				request.post(RequestBody.create(JSON, payload))
					.addHeader("Content-Type", "application/json")
					.addHeader("Content-Encoding", "gzip");
			} else {
				request.post(new MultipartBody.Builder()
					.setType(MultipartBody.FORM)
					.addFormDataPart("payload", "payload.json.gz", RequestBody.create(GZIP, payload))
					.addFormDataPart("screenshot", "screenshot.jpg", RequestBody.create(JPEG, screenshotJpeg))
					.build());
			}

			httpClient.newCall(request.build()).enqueue(new Callback() {
				@Override
				public void onFailure(Call call, IOException e) {
					log.error("Failed to send data to webhook: {}", e.getMessage());
				}

				@Override
				public void onResponse(Call call, Response response) {
					try {
						if (!response.isSuccessful()) {
							log.warn("Webhook returned non-successful status: {}", response.code());
							return;
						}
						if (onResponse == null || response.body() == null) return;
						JsonObject parsed = parseJsonOrNull(response);
						if (parsed == null) return;
						try {
							onResponse.accept(parsed);
						} catch (Exception e) {
							log.warn("Webhook response handler failed: {}", e.getMessage());
						}
					} finally {
						response.close();
					}
				}
			});
		} catch (IOException e) {
			log.error("Failed to prepare webhook data: {}", e.getMessage());
		} catch (Exception e) {
			log.error("Unexpected error preparing webhook", e);
		}
	}

	private static byte[] gzip(byte[] bytes) throws IOException {
		ByteArrayOutputStream byteStream = new ByteArrayOutputStream();
		try (GZIPOutputStream gzipStream = new GZIPOutputStream(byteStream)) {
			gzipStream.write(bytes);
		}
		return byteStream.toByteArray();
	}

	private JsonObject parseJsonOrNull(Response response) {
		try {
			return gson.fromJson(response.body().string(), JsonObject.class);
		} catch (Exception e) {
			log.warn("Failed to parse webhook response: {}", e.getMessage());
			return null;
		}
	}
}

package com.revalclan.util;

import net.runelite.api.Client;
import net.runelite.api.WorldType;

import java.util.ArrayList;
import java.util.List;

/**
 * World-type helpers. Payloads are stamped with WorldType flag names;
 * the backend owns the regular-worlds-only rule.
 */
public final class Worlds {
	private Worlds() {}

	/** Is the client on a seasonal (leagues) world? */
	public static boolean isSeasonal(Client client) {
		return client.getWorldType().contains(WorldType.SEASONAL);
	}

	/** WorldType flag names of the current world. */
	public static List<String> flagNames(Client client) {
		List<String> flags = new ArrayList<>();
		for (WorldType t : client.getWorldType()) {
			flags.add(t.name());
		}
		return flags;
	}
}

